// The MIT License - Copyright (c) 2022 Garrett Gunnell
// Adapted from https://github.com/GarrettGunnell/Post-Processing/
// blob/871a7ffcc44174f237b4c0127db51026c438d7a4/Assets/Kuwahara%20Filter/AnisotropicKuwahara.shader

vec4 $(name)_calc_eigenvectors(vec2 uv) {
	vec2 d = 1.0/vec2($s);
	vec3 Sx = (
		 1.0 * $in(uv + vec2(-d.x, -d.y)).rgb +
		 2.0 * $in(uv + vec2(-d.x,  0.0)).rgb +
		 1.0 * $in(uv + vec2(-d.x,  d.y)).rgb +
		-1.0 * $in(uv + vec2(d.x, -d.y)).rgb +
		-2.0 * $in(uv + vec2(d.x,  0.0)).rgb +
		-1.0 * $in(uv + vec2(d.x,  d.y)).rgb
	) * 0.25;

	vec3 Sy = (
		 1.0 * $in(uv + vec2(-d.x, -d.y)).rgb +
		 2.0 * $in(uv + vec2( 0.0, -d.y)).rgb +
		 1.0 * $in(uv + vec2( d.x, -d.y)).rgb +
		-1.0 * $in(uv + vec2(-d.x, d.y)).rgb +
		-2.0 * $in(uv + vec2( 0.0, d.y)).rgb +
		-1.0 * $in(uv + vec2( d.x, d.y)).rgb
	) * 0.25;

	return vec4(dot(Sx, Sx), dot(Sy, Sy), dot(Sx, Sy), 1.0);
}

// The MIT License - Copyright (c) 2022 Garrett Gunnell
// Adapted from https://github.com/GarrettGunnell/Post-Processing/
// blob/871a7ffcc44174f237b4c0127db51026c438d7a4/Assets/Kuwahara%20Filter/AnisotropicKuwahara.shader

vec3 $(name)_anisotropic_kuwahara(vec2 uv, int size, float _sharpness, float _ecc) {
	float sharpness = mix(3.0, 18.0, clamp(_sharpness, 0.0, 1.0));
	int _KernelSize = max(0, size * 2);
	const float alpha = 1.0; const float _Hardness = 8.0; const float _ZeroCrossing = 0.58;
	float zeta = 1.0 / (float(_KernelSize) / 2.0);

	float ecc = mix(0.7, 1.5, clamp(_ecc, 0.0, 1.0));

	vec4 g = $b(uv);
	float lambda1 = 0.5 * (g.y + g.x + sqrt(g.y * g.y - 2.0 * g.x * g.y + g.x * g.x + 4.0 * g.z * g.z));
	float lambda2 = 0.5 * (g.y + g.x - sqrt(g.y * g.y - 2.0 * g.x * g.y + g.x * g.x + 4.0 * g.z * g.z));

	vec2 v = vec2(lambda1 - g.x, -g.z);
	float A = (lambda1 + lambda2 > 0.0) ? (lambda1 - lambda2) / (lambda1 + lambda2) : 0.0;
	vec4 t = vec4(length(v) > 0.0 ? normalize(v) : vec2(0.0, 1.0), 0.0, A);

	int kernelRadius = _KernelSize / 2;
	float a = float(kernelRadius) * clamp((alpha + t.w) / alpha, 0.1, 2.0);
	float b = float(kernelRadius) * clamp(alpha / (alpha + t.w), 0.1, 2.0);

	float cos_phi = t.x;
	float sin_phi = t.y;

	mat2 R = mat2(vec2(cos_phi, -sin_phi), vec2(sin_phi, cos_phi));
	mat2 S = mat2(vec2(0.5 / a / ecc, 0.0), vec2(0.0, 0.5 / b * ecc));

	mat2 SR = S * R;

	int max_x = int(sqrt(a * a * cos_phi * cos_phi + b * b * sin_phi * sin_phi));
	int max_y = int(sqrt(a * a * sin_phi * sin_phi + b * b * cos_phi * cos_phi));

	float zeroCross = _ZeroCrossing;
	float sinZeroCross = sin(zeroCross);
	float eta = (zeta + cos(zeroCross)) / (sinZeroCross * sinZeroCross);

	vec4 m[8];
	vec3 s[8];

	for (int k = 0; k < 8; ++k) {
		m[k] = vec4(0.0);
		s[k] = vec3(0.0);
	}

	for (int y = -max_y; y <= max_y; ++y) {
		for (int x = -max_x; x <= max_x; ++x) {
			vec2 v = SR * vec2(float(x), float(y));
			if (dot(v, v) <= 0.125) {
				vec3 c = $in( uv + vec2(float(x), float(y)) * 1.0/vec2($s) ).rgb;
				c = clamp(c, vec3(0.0), vec3(1.0));
				float sum = 0.0;
				float w[8];
				float z, vxx, vyy;

				 // Calculate Polynomial Weights
				vxx = zeta - eta * v.x * v.x;
				vyy = zeta - eta * v.y * v.y;
				z = max(0.0, v.y + vxx);
				w[0] = z * z;
				sum += w[0];
				z = max(0, -v.x + vyy); 
				w[2] = z * z;
				sum += w[2];
				z = max(0.0, -v.y + vxx); 
				w[4] = z * z;
				sum += w[4];
				z = max(0.0, v.x + vyy); 
				w[6] = z * z;
				sum += w[6];
				 v = sqrt(2.0) / 2.0 * vec2(v.x - v.y, v.x + v.y);
				vxx = zeta - eta * v.x * v.x;
				vyy = zeta - eta * v.y * v.y;
				z = max(0, v.y + vxx); 
				w[1] = z * z;
				sum += w[1];
				z = max(0.0, -v.x + vyy); 
				w[3] = z * z;
				sum += w[3];
				z = max(0.0, -v.y + vxx); 
				w[5] = z * z;
				sum += w[5];
				z = max(0.0, v.x + vyy); 
				w[7] = z * z;
				sum += w[7];

				float g = exp(-3.125 * dot(v, v)) / sum;

				for (int k = 0; k < 8; ++k) {
					float wk = w[k] * g;
					m[k] += vec4(c * wk, wk);
					s[k] += c * c * wk;
				}
			}
		}
	}

	vec4 result = vec4(0.0);
	for (int k = 0; k < 8; ++k) {
		m[k].rgb /= m[k].w;
		s[k] = abs(s[k] / m[k].w - m[k].rgb * m[k].rgb);

		float sigma2 = s[k].r + s[k].g + s[k].b;
		float w = 1.0 / (1.0 + pow(_Hardness * 1000.0 * sigma2, 0.5 * sharpness));

		result += vec4(m[k].rgb * w, w);
	}

	return clamp(result.rgb / result.w, vec3(0.0), vec3(1.0));
}

shader_model.global:
float pavement(vec2 uv, float bevel, float mortar) {
	uv = abs(uv-vec2(0.5));
	return clamp((0.5*(1.0-mortar)-max(uv.x, uv.y))/max(0.0001, bevel), 0.0, 1.0);
}

vec4 arc_pavement(vec2 uv, float acount, float lcount, out vec2 seed) {
	float radius = (0.5/sqrt(2.0));
	float uvx = uv.x;
	uv.x = 0.5*fract(uv.x+0.5)+0.25;
	float center = (uv.x-0.5)/radius;
	center *= center;
	center = floor(acount*(uv.y-radius*sqrt(1.0-center))+0.5)/acount;
	vec2 v = uv-vec2(0.5, center);
	float cornerangle = 0.85/acount+0.25*PI;
	float acountangle = (PI-2.0*cornerangle)/(lcount+floor(mod(center*acount, 2.0)));
	float angle = mod(atan(v.y, v.x), 2.0*PI);
	float base_angle;
	float local_uvy = 0.5+acount*(length(v)-radius)*(1.66-0.71*cos(1.44*(angle-PI*0.5)));
	vec2 local_uv;
	if (angle < cornerangle) {
		base_angle = 0.25*PI;
		local_uv = vec2((angle-0.25*PI)/cornerangle*0.4*acount+0.55, 1.0-local_uvy);
		seed = vec2(fract(center), 0.0);
	} else if (angle > PI-cornerangle) {
		base_angle = 0.75*PI;
		local_uv = vec2(local_uvy, 0.45-(0.75*PI-angle)/cornerangle*0.4*acount);
		seed = vec2(fract(center), 0.0);
	} else {
		base_angle = cornerangle+(floor((angle-cornerangle)/acountangle)+0.5)*acountangle;
		local_uv = vec2((angle-base_angle)/acountangle+0.5, 1.0-local_uvy);
		seed = vec2(fract(center), base_angle);
	}
	vec2 brick_center = vec2(0.5, center)+radius*vec2(cos(base_angle), sin(base_angle));
	return vec4(brick_center.x+uvx-uv.x, brick_center.y, local_uv);
}

shader_model.instance:
vec3 $(name)_compare(vec2 uv, float size) {
	float iter = $in(uv).b;
	size = size / pow(2.0, (iter * 100.0) );
	iter += 0.01;
	float pixel_offset = 1.0 / size;
	vec2 half_res_uv = floor(uv * size / 2.0) / size * 2.0 + pixel_offset / 2.0;
	vec3 values[4];
	values[0] = $in(half_res_uv);
	values[1] = $in(half_res_uv + vec2(pixel_offset, 0.0));
	values[2] = $in(half_res_uv + vec2(0.0, pixel_offset));
	values[3] = $in(half_res_uv + vec2(pixel_offset, pixel_offset));

	float lowest = 1.0;
	float highest = 0.0;

	for (int i = 0; i < 4; i++) {
		lowest = values[i].r < lowest ? values[i].r : lowest;
		highest = values[i].g > highest ? values[i].g : highest;
	}

	return vec3( lowest, highest , iter);
}

shader_model.global:
float beehive_dist(vec2 p){
	vec2 s = vec2(1.0, 1.73205080757);
	p = abs(p);
	return max(dot(p, s*.5), p.x);
}

vec4 beehive_center(vec2 p) {
	vec2 s = vec2(1.0, 1.73205080757);
	vec4 hC = floor(vec4(p, p - vec2(.5, 1))/vec4(s,s)) + .5;
	vec4 h = vec4(p - hC.xy*s, p - (hC.zw + .5)*s);
	return dot(h.xy, h.xy)<dot(h.zw, h.zw) ? vec4(h.xy, hC.xy) : vec4(h.zw, hC.zw + 9.73);
}

