vec4 oldbricks_uneven(vec2 uv, int iterations, float min_size, float randomness, float seed) {
	vec2 a = vec2(0.0);
	vec2 b = vec2(1.0);

	for (int i = 0; i < iterations; ++i) {
		vec2 size = b-a;
		if (max(size.x, size.y) < min_size) {
		break;
		}
		float x = rand(rand2(vec2(rand(a+b), seed)))*randomness+(1.0-randomness)*0.5;
		if (size.x > size.y) {
			x *= size.x;
			if (uv.x > a.x+x) {
				a.x += x;
			} else {
				b.x = a.x + x;
			}
		} else {
			x *= size.y;
			if (uv.y > a.y+x) {
				a.y += x;
			} else {
				b.y = a.y + x;
			}
		}
	}
	return vec4(a, b);
}

