float brick_cut(vec2 id, vec2 size, float random, float seed) {
	return 0.5 + (rand(mod(id, size)+seed) - 0.5) * random;
}

vec4 bricks_uneven3(vec2 uv, vec2 size, float random, float seed) {
	vec2 fl = floor(uv);
	uv = fract(uv);
	uv *= size;

	vec2 cell_id = floor(uv);
	vec2 cell_uv = fract(uv);

	// We generate a random value for each cell. 
	// These values are used to decide where to cut each cell in half.
	// We cut them every other horizontally and verticall in a checkerlike pattern.
	// We go through each cell and check all the cells around it (that's why we need to generate 9 values.
	// We can then calculate the brick rects based on where we find the cuts in the surrounding cells.

	float current = brick_cut(cell_id, size, random, seed);
	float top = brick_cut(cell_id + vec2(0.0, -1.0), size, random, seed);
	float top_right = brick_cut(cell_id + vec2(1.0, -1.0), size, random, seed);
	float right = brick_cut(cell_id + vec2(1.0, 0.0), size, random, seed);
	float bottom_right = brick_cut(cell_id + vec2(1.0, 1.0), size, random, seed);
	float bottom = brick_cut(cell_id + vec2(0.0, 1.0), size, random, seed);
	float bottom_left = brick_cut(cell_id + vec2(-1.0, 1.0), size, random, seed);
	float left = brick_cut(cell_id + vec2(-1.0, 0.0), size, random, seed);
	float top_left = brick_cut(cell_id + vec2(-1.0, -1.0), size, random, seed);

	vec4 bricks = vec4(cell_id, cell_id);

	// Horizontal
	if (mod(cell_id.x + cell_id.y, 2.0) > 0.5) {
		if ( current > cell_uv.y ) {
			if ( top > cell_uv.x) {
				bricks.x -= 1.0 - left;
				bricks.y -= 1.0 - top_left;
				bricks.z += top;
				bricks.w += current;
			} else {
				bricks.x += top;
				bricks.y -= 1.0 - top_right;
				bricks.z += 1.0 + right;
				bricks.w += current;
			}
		} else {
			if ( bottom > cell_uv.x) {
				bricks.x -= 1.0 - left;
				bricks.y += current;
				bricks.z += bottom;
				bricks.w += 1.0 + bottom_left;
			} else {
				bricks.x += bottom;
				bricks.y += current;
				bricks.z += 1.0 + right;
				bricks.w += 1.0 + bottom_right;
			}
		}
	// Vertical
	} else { 
		if ( current > cell_uv.x ) {
			if (left > cell_uv.y) {
				bricks.x -= 1.0 - top_left;
				bricks.y -= 1.0 - top;
				bricks.z += current;
				bricks.w += left;
			} else {
				bricks.x -= 1.0 - bottom_left;
				bricks.y += left;
				bricks.z += current;
				bricks.w += 1.0 + bottom;	
			}
		} else {
			if (right > cell_uv.y) {
				bricks.x += current;
				bricks.y -= 1.0 - top;
				bricks.z += 1.0 + top_right;
				bricks.w += right;
			} else {
				bricks.x += current;
				bricks.y += right;
				bricks.z += 1.0 + bottom_right;
				bricks.w += 1.0 + bottom;
			}
		}
	}

