shader_model.instance:
vec4 triplanar_$(name)(vec2 uv, float k) {
	vec3 p = mesh_aabb_position+texture(mesh_inv_uv_tex, uv).xyz*mesh_aabb_size;
	vec3 n = 2.0*(texture(mesh_normal_tex, uv).xyz-vec3(0.5));

	// project+fetch
	vec4 x = $in(p.zy);
	vec4 y = $in(p.zx);
	vec4 z = $in(p.xy);

	// blend factors
	vec3 w = pow(abs(n), vec3(k));
	// blend and return
	return (x*w.x + y*w.y + z*w.z) / (w.x + w.y + w.z);
}

shader_model.global:
float cairo_round(vec2 uv, float angle, float k) {
	vec2 cell = floor(uv);
	float ca = cos(angle);
	float sa = sin(angle);
	vec2 corner = fract(uv)-0.5;
	uv = 0.5-abs(corner);
	uv = mix(uv, uv.yx, mod(cell.x+cell.y, 2.0));
	float side = dot(vec2(-sa, ca), uv);
	float d1 = abs(side);
	float d2 = abs(dot(vec2(-sa, ca), mix(vec2(uv.x, 1.0-uv.y), vec2(1.0-uv.x, uv.y), step(side, 0.0))));
	float d3 = abs(dot(vec2(ca, sa), uv));
	float d4 = mix(0.5-uv.x, 0.5-uv.y, step(side, 0.0));
	return clamp(-log2(exp2(-k*d1)+exp2(-k*d2)+exp2(-k*d3)+exp2(-k*d4))/k, 0.0, 1.0);
}

vec4 cairo_bbox(vec2 uv, float angle) {
	vec2 cell = floor(uv);
	float cell_type = mod(cell.x+cell.y, 2.0);
	float ca = cos(angle);
	float sa = sin(angle);
	float l = 0.0;
	float r = 1.0;
	float b = 0.0;
	float t = 1.0;
	vec2 corner = fract(uv)-0.5;
	uv = 0.5-abs(corner);
	uv = mix(uv, uv.yx, cell_type);
	float side = dot(vec2(-sa, ca), uv);
	float ta = tan(angle);
	float c = min(0.5, 0.5/ta);
	float s = min(0.5, 0.5*ta);
	if (cell_type > 0.5) {
		if (side > 0.0) {
			if (corner.y > 0.0) {
				t = 1.0+s;
				b = 1.0-c;
			} else {
				t = c;
				b = -s;
			}
		} else {
			if (corner.x > 0.0) {
				l = 1.0-s;
				r = 1.0+c;
			} else {
				l = -c;
				r = s;
			}
		}
	} else {
		if (side > 0.0) {
			if (corner.x > 0.0) {
				l = 1.0-c;
				r = 1.0+s;
			} else {
				l = -s;
				r = c;
			}
		} else {
			if (corner.y > 0.0) {
				t = 1.0+c;
				b = 1.0-s;
			} else {
				t = s;
				b = -c;
			}
		}
	}
	float d1 = abs(side);
	float d3 = abs(dot(vec2(ca, sa), uv));
	float d4 = mix(0.5-uv.x, 0.5-uv.y, step(side, 0.0));
	return vec4(cell.x+l, cell.y+b, r-l, t-b);
}

shader_model.instance:
vec4 splatter_$(name)(vec2 uv, int count, int rings, inout vec3 instance_uv, vec2 seed) {
	float c = 0.0;
	vec3 rc = vec3(0.0);
	vec3 rc1;
	seed = rand2(seed);
	for (int i = 0; i < count; ++i) {
		float a = -1.57079632679+6.28318530718*float(i)*$rings/float(count);
		float rings_distance = ceil(float(i+1)*float(rings)/float(count))/float(rings);
		float spiral_distance = float(i+1)/float(count);
		vec2 pos = $radius*mix(rings_distance, spiral_distance, $spiral)*vec2(cos(a), sin(a));
		float mask = $mask(fract(pos-vec2(0.5)));
		if (mask > 0.01) {
			vec2 pv = uv-0.5-pos;
			rc1 = rand3(seed);
			seed = rand2(seed);
			float angle = (seed.x * 2.0 - 1.0) * $rotate * 0.01745329251 + (a+1.57079632679) * $i_rotate;
			float ca = cos(angle);
			float sa = sin(angle);
			pv = vec2(ca*pv.x+sa*pv.y, -sa*pv.x+ca*pv.y);
			pv /= mix(1.0, float(i+1)/float(count+1), $i_scale);
			pv /= vec2($scale_x, $scale_y);
			pv *= (seed.y-0.5)*2.0*$scale+1.0;
			pv += vec2(0.5);
			seed = rand2(seed);
			vec2 test_value = clamp(pv, vec2(0.0), vec2(1.0));
			if (pv.x != test_value.x || pv.y != test_value.y) {
				continue;
			}
			vec2 full_uv = pv;
			pv = get_from_tileset($inputs, seed.x, pv);
			float c1 = $in.variation(pv, $variations ? seed.x : 0.0)*mask*(1.0-$value*seed.x);
			c = max(c, c1);
			rc = mix(rc, rc1, step(c, c1));
			instance_uv = mix(instance_uv, vec3(full_uv, seed.x), step(c, c1));
		}
	}
	return vec4(rc, c);
}

