// Returns avg color in .rgb, std in .a
vec4 $(name)_SampleQuadrant(vec2 uv, int x1, int x2, int y1, int y2, float n) {
	float luminance_sum = 0.0;
	float luminance_sum2 = 0.0;
	vec3 col_sum = vec3(0.0);

	for (int x = x1; x <= x2; ++x) {
		for (int y = y1; y <= y2; ++y) {
			vec3 _sample = $in(uv + vec2(float(x), float(y)) / $s);
			float l = dot(_sample, vec3(0.299, 0.587, 0.114));
			luminance_sum += l;
			luminance_sum2 += l * l;
			col_sum += clamp(_sample, vec3(0.0), vec3(1.0));
		}
	}

	float mean = luminance_sum / n;
	float std = abs(luminance_sum2 / n - mean * mean);

	return vec4(col_sum / n, std);
}

vec3 $(name)_classic_kuwahara(vec2 uv, int radius) {
	float windowSize = 2.0 * float(radius + 1);
	int quadrantSize = int(ceil(windowSize / 2.0));
	float numSamples = float(quadrantSize * quadrantSize);

	vec4 q1 = $(name)_SampleQuadrant(uv, -radius, 0, -radius, 0, numSamples);
	vec4 q2 = $(name)_SampleQuadrant(uv, 0, radius, -radius, 0, numSamples);
	vec4 q3 = $(name)_SampleQuadrant(uv, 0, radius, 0, radius, numSamples);
	vec4 q4 = $(name)_SampleQuadrant(uv, -radius, 0, 0, radius, numSamples);

	float minstd = min(q1.a, min(q2.a, min(q3.a, q4.a)));
	vec4 q = vec4(float(q1.a == minstd), float(q2.a == minstd), float(q3.a == minstd), float(q4.a == minstd));

	if (dot(q, vec4(1.0)) > 1.0)
		return clamp((q1.rgb + q2.rgb + q3.rgb + q4.rgb) / 4.0, vec3(0.0), vec3(1.0));
	else
		return clamp(q1.rgb * q.x + q2.rgb * q.y + q3.rgb * q.z + q4.rgb * q.w, vec3(0.0), vec3(1.0));
}

