shader_model.global:
// Converts a color from linear light gamma to sRGB gamma
vec4 fromLinear(vec4 linearRGB)
{
	bvec3 cutoff = lessThan(linearRGB.rgb, vec3(0.0031308));
	vec3 higher = vec3(1.055)*pow(linearRGB.rgb, vec3(1.0/2.4)) - vec3(0.055);
	vec3 lower = linearRGB.rgb * vec3(12.92);

	return vec4(mix(higher, lower, cutoff), linearRGB.a);
}

// Converts a color from sRGB gamma to linear light gamma
vec4 toLinear(vec4 sRGB)
{
	bvec3 cutoff = lessThan(sRGB.rgb, vec3(0.04045));
	vec3 higher = pow((sRGB.rgb + vec3(0.055))/vec3(1.055), vec3(2.4));
	vec3 lower = sRGB.rgb/vec3(12.92);

	return vec4(mix(higher, lower, cutoff), sRGB.a);
}

vec3 color_dots(vec2 uv, float size, float seed) {
	vec2 seed2 = rand2(vec2(seed, 1.0-seed));
	uv /= size;
	vec2 point_pos = floor(uv)+vec2(0.5);
	return rand3(seed2+point_pos);
}

vec3 from_rgb_to_rgb(vec3 c) {return c;}
vec3 to_rgb_from_rgb(vec3 c) {return c;}

vec3 from_rgb_to_hsv(vec3 c) {
	vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
	vec4 p = c.g < c.b ? vec4(c.bg, K.wz) : vec4(c.gb, K.xy);
	vec4 q = c.r < p.x ? vec4(p.xyw, c.r) : vec4(c.r, p.yzx);

	float d = q.x - min(q.w, q.y);
	float e = 1.0e-10;
	return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 to_rgb_from_hsv(vec3 c) {
	vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
	vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
	return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
// Matrix coefficients taken from https://en.wikipedia.org/wiki/YCbCr#ITU-R_BT.709_conversion
vec3 from_rgb_to_yuv(vec3 c) {
	return c * mat3(
		vec3( 0.2126,  0.7152,  0.0722),
		vec3(-0.1146, -0.3854,  0.5),
		vec3( 0.5,    -0.4542, -0.0458)
	);
}
vec3 to_rgb_from_yuv(vec3 c) {
	return c * mat3(
		vec3(1.0,  0.0,     1.5748),
		vec3(1.0, -0.1873, -0.4681),
		vec3(1.0,  1.8556,  0.0)
	);
}

