vec4 $(name)_crop(vec2 uv) {
	vec2 new_uv = uv * vec2( $x2 - $x1, $y2 - $y1) + vec2($x1 + 0.5, $y1 + 0.5);
	float mask = float(floor(uv) == vec2(0.0));
	if ($edge == 0) {
		vec4 col = $in(new_uv);
		return col * mask;
	} else if ($edge == 1) {
		new_uv = fract(uv) * vec2( $x2 - $x1, $y2 - $y1) + vec2($x1 + 0.5, $y1 + 0.5);
		return $in(new_uv);
	} else if ($edge == 2){
		return $in(new_uv);
	} else {
		vec4 col = $in(new_uv);
		return mix($edge_color, col, mask);
	}
}

vec2 $(name)_sca_fac(vec2 uv) {
	vec2 sca = abs(vec2($x2 - $x1, $y2 - $y1));
	return sca / max(sca.x, sca.y) * 0.5 + 0.5;
}

vec4 $(name)_crop2(vec2 uv) {
	uv -= vec2($x1 + 0.5, $y1 + 0.5);
	vec2 new_uv = mod(uv, vec2( $x2 - $x1, $y2 - $y1) ) + vec2($x1 + 0.5, $y1 + 0.5);
	return $in(new_uv);
}

vec4 $(name)_crop_preview(vec2 uv) {
	float mask = uv.x - 0.5 > $x1 && uv.x - 0.5 < $x2 && uv.y - 0.5 > $y1 && uv.y - 0.5 < $y2 ? 1.0 : $pa;
	return $in(uv) * mask;
}

float $(name)_fade_mask(vec2 uv, float fade_width) {
	uv -= vec2($x1 + 0.5, $y1 + 0.5);
	float vertical_mask = clamp(uv.x / fade_width + 0.5, 0.0, 1.0);
	uv -= vec2( $x2 - $x1, $y2 - $y1);
	vertical_mask *= clamp(-uv.x / fade_width + 0.5, 0.0, 1.0);
	return vertical_mask;
}

