shader_model.global:
float cross2( in vec2 a, in vec2 b ) { return a.x*b.y - a.y*b.x; }

// signed distance to a quadratic bezier
vec2 sdBezier( in vec2 pos, in vec2 A, in vec2 B, in vec2 C ) {	
	vec2 a = B - A;
	vec2 b = A - 2.0*B + C;
	vec2 c = a * 2.0;
	vec2 d = A - pos;

	float kk = 1.0/dot(b,b);
	float kx = kk * dot(a,b);
	float ky = kk * (2.0*dot(a,a)+dot(d,b))/3.0;
	float kz = kk * dot(d,a);	  

	float res = 0.0;
	float sgn = 0.0;

	float p = ky - kx*kx;
	float p3 = p*p*p;
	float q = kx*(2.0*kx*kx - 3.0*ky) + kz;
	float h = q*q + 4.0*p3;
	float rvx;

	if( h>=0.0 ) { // 1 root
		h = sqrt(h);
		vec2 x = (vec2(h,-h)-q)/2.0;
		vec2 uv = sign(x)*pow(abs(x), vec2(1.0/3.0));
		rvx = uv.x+uv.y-kx;
		float t = clamp(rvx, 0.0, 1.0);
		vec2 q2 = d+(c+b*t)*t;
		res = dot(q2, q2);
		sgn = cross2(c+2.0*b*t, q2);
	} else {   // 3 roots
		float z = sqrt(-p);
		float v = acos(q/(p*z*2.0))/3.0;
		float m = cos(v);
		float n = sin(v)*1.732050808;
		vec3  t = clamp(vec3(m+m,-n-m,n-m)*z-kx, 0.0, 1.0);
		vec2  qx=d+(c+b*t.x)*t.x; float dx=dot(qx, qx), sx = cross2(c+2.0*b*t.x,qx);
		vec2  qy=d+(c+b*t.y)*t.y; float dy=dot(qy, qy), sy = cross2(c+2.0*b*t.y,qy);
		if( dx<dy ) { res=dx; sgn=sx; rvx = t.x; } else { res=dy; sgn=sy; rvx = t.y; }
	}

	return vec2(rvx, sqrt(res)*sign(sgn));
}

shader_model.instance:
vec3 tile_$(name)(vec2 p, vec2 size, float offset) {
	float best_d = -10.0;
	vec2 best_corner;
	for (float x = -1.0; x <= 1.0; x += 1.0) {
		for (float y = -1.0; y <= 1.0; y += 1.0) {
			vec2 corner = floor(p*size+vec2(x, y));
			corner.x -= fract(offset*corner.y);
			vec2 uv = p*size-corner;
			if ($mirror && (int(corner.y) & 1) == 1) {
				uv.x = 1.0-uv.x;
				uv.y = 1.0-uv.y;
			}
			float d = -$shape(uv);
			if (d > best_d) {
				best_d = d;
				best_corner = fract(round(corner/size*4096.0)/4096.0);
			}
		}
	}
	float mortar = $mortar*$mortar_map(p);
	float bevel = $bevel*$bevel_map(p);
	return vec3(clamp((best_d-mortar)/bevel, 0.0, 1.0), best_corner);
}

shader_model.global:
vec2 get_from_tileset(float count, float seed, vec2 uv) {
	return clamp((uv+floor(rand2(vec2(seed))*count))/count, vec2(0.0), vec2(1.0));
}

vec2 old_custom_uv_transform(vec2 uv, vec2 cst_scale, float rnd_rotate, float rnd_scale, vec2 seed) {
	seed = rand2(seed);
	uv -= vec2(0.5);
	float angle = (seed.x * 2.0 - 1.0) * rnd_rotate;
	float ca = cos(angle);
	float sa = sin(angle);
	uv = vec2(ca*uv.x+sa*uv.y, -sa*uv.x+ca*uv.y);
	uv *= (seed.y-0.5)*2.0*rnd_scale+1.0;
	uv /= cst_scale;
	uv += vec2(0.5);
	return uv;
}

vec2 get_from_tileset_extend(float count, float seed, vec2 uv) {
	return (uv+floor(rand2(vec2(seed))*count))/count;
}

vec2 get_from_tileset_clamp(float count, float seed, vec2 uv) {
	return clamp((uv+floor(rand2(vec2(seed))*count))/count, vec2(0.0), vec2(1.0));
}

vec2 get_from_tileset_repeat(float count, float seed, vec2 uv) {
	return fract(uv+floor(rand2(vec2(seed))*count))/count;
}


vec2 custom_uv_transform(vec2 uv, vec2 cst_scale, float rnd_rotate, float rnd_scale, vec2 seed) {
	seed = rand2(seed);
	uv -= vec2(0.5);
	float angle = (seed.x * 2.0 - 1.0) * rnd_rotate;
	float ca = cos(angle);
	float sa = sin(angle);
	uv = vec2(ca*uv.x+sa*uv.y, -sa*uv.x+ca*uv.y);
	uv *= (seed.y-0.5)*2.0*rnd_scale+1.0;
	uv /= cst_scale;
	uv += vec2(0.5);
	return uv;
}

