vec3 $(name)_distance_h(vec2 uv, bool tile) {
	vec2 e = vec2(1.0/$s, 0.0);
	int steps = int($s*$d);
	float rv = 0.0;
	vec2 source_uv;
	for (int i = 0; i < steps; ++i) {
		source_uv = uv+float(i)*e;
		if ((tile || (source_uv.x >= 0.0 && source_uv.x <= 1.0)) && $in(source_uv) > 0.5) {
			rv = 1.0-float(i)*e.x/$d;
			break;
		}
		source_uv = uv-float(i)*e;
		if ((tile || (source_uv.x >= 0.0 && source_uv.x <= 1.0)) && $in(source_uv) > 0.5) {
			rv = 1.0-float(i)*e.x/$d;
			break;
		}
	}
	return vec3(rv, source_uv);
}

shader_model.global:
float dilate_distance_euclidian(float x, float y, float d) {
	return 1.0-sqrt((1.0-x)*(1.0-x)+y*y/d/d);
}

float dilate_distance_manhattan(float x, float y, float d) {
	return 1.0-(abs(1.0-x)+abs(y)/d);
}

float dilate_distance_chebyshev(float x, float y, float d) {
	return 1.0-max(abs(1.0-x), abs(y)/d);
}

shader_model.instance:
vec3 $(name)_distance_v(vec2 uv, bool tile) {
	vec2 e = vec2(0.0, 1.0/$s);
	int steps = int($s*$d);
	vec3 p = vec3($in(uv).xy, uv.y);
	vec2 source_uv;
	for (int i = 0; i < steps; ++i) {
		vec2 dx = float(i)*e;
		source_uv = uv+dx;
		if (tile || (source_uv.y >= 0.0 && source_uv.y < 1.0)) {
			vec3 p2 = vec3($in(source_uv).xy, source_uv.y);
			if (p2.x > p.x) {
				p2.x = dilate_distance_$distance(p2.x, dx.y, $d);
				p = mix(p, p2, step(p.x, p2.x));
			}
		}
		source_uv = uv-dx;
		if (tile || (source_uv.y >= 0.0 && source_uv.y < 1.0)) {
			vec3 p2 = vec3($in(source_uv).xy, source_uv.y);
			if (p2.x > p.x) {
				p2.x = dilate_distance_$distance(p2.x, dx.y, $d);
				p = mix(p, p2, step(p.x, p2.x));
			}
		}
	}
	return p;
}

vec4 $(name)_fct(vec2 uv) {
	vec2 e = vec2(cos($angle*0.01745329251), -sin($angle*0.01745329251))/$size;
	vec4 rv = vec4(0.0);
	float sum = 0.0;
	float sigma = $sigma*$amount(uv);
	for (float i = $mode; i <= 50.0; i += 1.0) {
		float coef = exp(-0.5*(pow(i/sigma, 2.0)))/(6.28318530718*sigma*sigma);
		rv += $in(uv+i*e)*coef;
		sum += coef;
	}
	return rv/sum;
}

