	// vec2 v1 = ac+x*abcd;
	// vec2 v2 = pa+x*ab;
	// (ac.x+x*abcd.x)*(pa.y+x*ab.y)-(ac.y+x*abcd.y)*(pa.x+x*ab.x) = 0;
	// (ac.x*pa.y-ac.y*pa.x)+x*(abcd.x*pa.y+ac.x*ab.y-abcd.y*pa.x-ac.y*ab.x)+x*x*(abcd.x*ab.y-abcd.y*ab.x) = 0
	float aa = abcd.x*ab.y-abcd.y*ab.x;
	float bb = abcd.x*pa.y+ac.x*ab.y-abcd.y*pa.x-ac.y*ab.x;
	float cc = ac.x*pa.y-ac.y*pa.x;
	float delta = bb*bb-4.0*aa*cc;
	if (abs(aa) < 0.00001) {
		return -cc/bb;
	} else if (delta >= 0.0) {
		float s1 = (-bb-sqrt(delta))/(2.0*aa);
		float s2 = (-bb+sqrt(delta))/(2.0*aa);
		return (abs(s1-0.5) < abs(s2-0.5)) ? s1 : s2;
	}
	return 0.0;
}

vec2 perspective_transform(vec2 p, vec2 a, vec2 b, vec2 c, vec2 d) {
	return vec2(perspective_transform_coord(p, a, b, d, c), perspective_transform_coord(p, a, d, b, c));
}

