vec4 distort_$(name)(vec2 uv) {
	vec2 p[] = $lattice;
	ivec2 lsize = $lattice_size;
	vec2 luv;
	bool inside = false;
	for (int y = 0; y < lsize.y; ++y) {
		int yi0 = y*(lsize.x+1);
		int yi1 = yi0+lsize.x+1;
		for (int x = 0; x < lsize.x; ++x) {
			luv = perspective_transform(uv, p[yi0+x], p[yi0+x+1], p[yi1+x+1], p[yi1+x]);
			vec2 luv_m05 = luv-vec2(0.5);
			inside = abs(luv_m05.x) < 0.5 && abs(luv_m05.y) < 0.5;
			if (inside) {
				luv += vec2(float(x), float(y));
				luv /= vec2(float(lsize.x), float(lsize.y));
				return $in(luv);
			}
		}
	}
	/*
		P0 = p0+x*(p1-p0)
		P1 = p3+x*(p2-p3)
		P = a+x*(b-a)+y*(d-a)+xy*(c-b)+xy*(a-d)
	*/
	return inside ? $in(luv) : vec4(0.0);
}

float $(name)_fct(vec2 uv) {
	vec3 e_base = vec3(1.0/$size, -1.0/$size, 0);
	vec3 ref = $in(uv);
	vec3 e = vec3(0);
	float rv = 0.0;
	for (int i = 0; i < int($width); ++i) {
		e += e_base;
		rv += length($in(uv+e.xy)-ref);
		rv += length($in(uv-e.xy)-ref);
		rv += length($in(uv+e.xx)-ref);
		rv += length($in(uv-e.xx)-ref);
		rv += length($in(uv+e.xz)-ref);
		rv += length($in(uv-e.xz)-ref);
		rv += length($in(uv+e.zx)-ref);
		rv += length($in(uv-e.zx)-ref);
		rv *= 2.0;
	}
	return rv*pow(2.0, -$width);
}

float $(name)_fct(vec2 uv) {
	vec3 e = vec3(1.0/$size, -1.0/$size, 0);
	vec3 rv = 8.0*$in(uv);
	rv -= $in(uv+e.xy);
	rv -= $in(uv-e.xy);
	rv -= $in(uv+e.xx);
	rv -= $in(uv-e.xx);
	rv -= $in(uv+e.xz);
	rv -= $in(uv-e.xz);
	rv -= $in(uv+e.zx);
	rv -= $in(uv-e.zx);
	rv = abs(rv);
	return max(rv.x, max(rv.y ,rv.z))*$size;
}

float $(name)_fct(vec2 uv) {
	vec2 e = vec2(1.0/$size, 0.0);
	vec3 rv = 4.0*$in(uv);
	rv -= $in(uv+e.xy);
	rv -= $in(uv-e.xy);
	rv -= $in(uv+e.yx);
	rv -= $in(uv-e.yx);
	rv = abs(rv);
	return max(rv.x, max(rv.y ,rv.z))*$size;
}

float $(name)_fct(vec2 uv) {
	vec2 e = vec2(1.0/$size, -1.0/$size);
	vec3 rv = 4.0*$in(uv);
	rv -= $in(uv+e.xy);
	rv -= $in(uv-e.xy);
	rv -= $in(uv+e.xx);
	rv -= $in(uv-e.xx);
	rv = abs(rv);
	return max(rv.x, max(rv.y ,rv.z))*$size;
}

float $(name)_fct(vec2 uv) {
	float pixels = max(1.0, $width);
	float e = 1.0/$size;
	float rv = 0.0;
	for (float dx = -pixels; dx <= pixels; dx += 1.0) {
		for (float dy = -pixels; dy <= pixels; dy += 1.0) {
			if (abs(dx) > 0.5 || abs(dy) > 0.5) {
				rv += $in(uv+e*vec2(dx, dy))*cos(atan(dy, dx)-$angle*3.14159265359/180.0)/length(vec2(dx, dy));
			}
		}
	}
	return $amount*rv/pixels+0.5;
}

