			if (abs(dx) > 0.5 || abs(dy) > 0.5) {
				rv += $in(uv+e*vec2(dx, dy))*cos(atan(dy, dx)-$angle*3.14159265359/180.0)/length(vec2(dx, dy));
			}
		}
	}
	return $amount*rv/pixels+0.5;
}

vec4 $(name)_blur(vec2 uv, vec2 scale, float sigma, int quality) {
	vec4 O = vec4(0.0);
	float samples = sigma * 4.0; 
	int LOD = max(0, int(log2(float(samples)))-quality-2);
	int sLOD = 1 << LOD;
	int s = max(1, int(samples/float(sLOD)));
	float sum = 0.0;
	for (int i = 0; i < s*s; i++) {
		vec2 d = vec2(float(i%s), float(i/s))*float(sLOD) - 0.5*float(samples);
		vec2 dd = d / sigma;
		float g = exp(-.5*dot(dd,dd))/(6.28*sigma*sigma);
		O += g * textureLod($in.texture, uv + scale * d, float(LOD));
		sum += g;
	}

	return O / sum;
}

