	for (int i = 0; i < octaves; i++) {
		float noise = cellular8_noise_2d(coord*size, size, offset, seed+float(i));
		for (int f = 0; f < folds; ++f) {
			noise = abs(2.0*noise-1.0);
		}
		value += noise * scale;
		normalize_factor += scale;
		size *= lacunarity;
		scale *= persistence;
	}
	return value / normalize_factor;
}

// MIT License Inigo Quilez - https://www.shadertoy.com/view/Xd23Dh
float voronoise_noise_2d( vec2 coord, vec2 size, float offset, float seed) {
	vec2 i = floor(coord) + rand2(vec2(seed, 1.0-seed)) + size;
	vec2 f = fract(coord);

	vec2 a = vec2(0.0);

	for( int y=-2; y<=2; y++ ) {
		for( int x=-2; x<=2; x++ ) {
			vec2  g = vec2( float(x), float(y) );
			vec3  o = rand3( mod(i + g, size) + vec2(seed) );
			o.xy += 0.25 * sin(offset * 6.28318530718 + 6.28318530718*o.xy);
			vec2  d = g - f + o.xy;
			float w = pow( 1.0-smoothstep(0.0, 1.414, length(d)), 1.0 );
			a += vec2(o.z*w,w);
		}
	}

	return a.x/a.y;
}

float fbm_2d_voronoise(vec2 coord, vec2 size, int folds, int octaves, float persistence, float lacunarity, float offset, float seed) {
	float normalize_factor = 0.0;
	float value = 0.0;
	float scale = 1.0;
	for (int i = 0; i < octaves; i++) {
		float noise = voronoise_noise_2d(coord*size, size, offset, seed+float(i));
		for (int f = 0; f < folds; ++f) {
			noise = abs(2.0*noise-1.0);
		}
		value += noise * scale;
		normalize_factor += scale;
		size *= lacunarity;
		scale *= persistence;
	}
	return value / normalize_factor;
}

// MIT License Inigo Quilez - https://www.shadertoy.com/view/clGyWm
float gabor(vec2 p, vec2 size, float offset, float seed)
{
	vec2  ip = floor(p);
	vec2  fp = fract(p);

	const float fr = TAU;
	const float fa = 4.0;

	float av = 0.0;
	float at = 0.0;
	for( float j = -2.0; j <= 2.0; j++ )
	for( float i = -2.0; i <= 2.0; i++ )
	{
		vec2 o = vec2( i, j );
		vec2 h = rand2(seed + mod(ip + o + size, size));
		vec2 r = fp - (o+h);

		vec2 kd = -1.0 + 2.0 * rand2(seed+ mod(ip + o + vec2(11.0, 31.0) + size, size));
		vec2 k = normalize(length(kd) > 0.0 ? kd : vec2(1.0));

		float d = dot(r, r);
		float l = dot(r, k);
		float w = exp(-fa * d);
		vec2 cs = vec2( cos(fr*l+(offset+seed)*TAU), sin(fr*l+(offset+seed)*TAU) );

		av += w*cs.x;
		at += w;
	}
	return av / at * 0.5 + 0.5;
}

float fbm_2d_gabor(vec2 coord, vec2 size, int folds, int octaves, float persistence, float lacunarity, float offset, float seed) {
	float normalize_factor = 0.0;
	float value = 0.0;
	float scale = 1.0;
	for (int i = 0; i < octaves; i++) {
		float noise = gabor(coord*size, size, offset, seed+float(i));
		for (int f = 0; f < folds; ++f) {
			noise = abs(2.0*noise-1.0);
		}
		value += noise * scale;
		normalize_factor += scale;
		size *= lacunarity;
		scale *= persistence;
	}
	return value / normalize_factor;
}

shader_model.instance:
float fbm_variations_$(name)(vec2 uv, int iterations, float persistance) {
	float v = 0.0;
	float keep = 1.0;
	float sum = 0.0;
	float seedvar = _seed_variation_;
	vec4 var = _controlled_variation_;
	var.$variable = 1.0;
	for (int i = 0; i < iterations; i++) {
		float input_v = $in.variation(uv, seedvar, var);
		v += input_v*keep;
		if ($randomize) {
			seedvar = rand(vec2(seedvar,sum));
		}
		sum += keep;
		var.$variable *= 2.0;
		keep *= persistance;
	}
	return v/sum;
}

shader_model.global:
float dilate_distance_euclidian(float x, float y, float d) {
	return 1.0-sqrt((1.0-x)*(1.0-x)+y*y/d/d);
}

float dilate_distance_manhattan(float x, float y, float d) {
	return 1.0-(abs(1.0-x)+abs(y)/d);
}

float dilate_distance_chebyshev(float x, float y, float d) {
	return 1.0-max(abs(1.0-x), abs(y)/d);
}

shader_model.instance:
vec3 $(name)_distance_v(vec2 uv) {
	vec2 e = vec2(0.0, 1.0/$s);
	int steps = int($s*$d);
	vec3 p = vec3(pack_4x16_to_2x32($in(uv)), uv.y);
	for (int i = 0; i < steps; ++i) {
		vec2 dx = float(i)*e;
		vec2 uv2 = fract(uv+dx);
		vec3 p2 = vec3(pack_4x16_to_2x32($in(uv2)), uv2.y);
		if (p2.x > p.x) {
			p2.x = dilate_distance_$distance(p2.x, dx.y, $d);
			p = mix(p, p2, step(p.x, p2.x));
		}
		uv2 = fract(uv-dx);
		p2 = vec3(pack_4x16_to_2x32($in(uv2)), uv2.y);
		if (p2.x > p.x) {
			p2.x = dilate_distance_$distance(p2.x, dx.y, $d);
			p = mix(p, p2, step(p.x, p2.x));
		}
	}
	return p;
}

vec3 $(name)_distance_h(vec2 uv) {
	vec2 e = vec2(1.0/$s, 0.0);
	int steps = int($s*$d);
	float rv = 0.0;
	vec2 source_uv;
	for (int i = 0; i < steps; ++i) {
		source_uv = uv+float(i)*e;
		if ($in(source_uv) > 0.5) {
			rv = 1.0-float(i)*e.x/$d;
			break;
		}
		source_uv = uv-float(i)*e;
		if ($in(source_uv) > 0.5) {
			rv = 1.0-float(i)*e.x/$d;
			break;
		}
	}
	return vec3(rv, source_uv);
}

vec4 $(name)_fill(vec2 uv) {
	vec4 ref_color = $colors(uv);
	float size = $s;
	int iterations = min(int(size), 1024);
	vec4 color = $in(fract(uv));
	if (color.z+color.w < 1.0/size) {
		return vec4(0.0);
	}
	vec2 offsets[4] = { vec2(1.0, 1.0), vec2(-1.0, 1.0), vec2(-1.0, -1.0), vec2(1.0, -1.0) };
	vec2 mult_base = vec2(1.0, 0.0);
	for (int o = 0; o < 4; ++o) {
		vec2 offset = offsets[o]/size;
		vec2 mult = mult_base;
		for (int d = 0; d < 2; ++d) {
			vec2 uv2 = uv;
			int l = 0;
			for (int i = 1; i < iterations; i += 1) {
				vec2 uv2_save = uv2;
				uv2 += offset*mult;
				vec4 color2 = $in(fract(uv2));
				if (ref_color != $colors(fract(uv2))) {
					if (l < 1) {
						mult = mult.yx;
						l += 1;
						uv2 = uv2_save;
						continue;
					}
					break;
				}
				l = 0;
				vec2 p1 = color.xy+floor(uv-color.xy);
				vec2 p2 = color2.xy+floor(uv2-color2.xy);
				vec2 p = min(p1, p2);
				vec2 s = max(p1+color.zw, p2+color2.zw)-p;
				color = mix(vec4(0.0, 0.0, 1.0, 1.0), vec4(fract(p), s), step(s.xyxy, vec4(1.0)));
			}
			mult = mult_base.yx;
		}
	}
	return floor(color*size)/size;
}

