	vec2 offsets[4] = { vec2(1.0, 1.0), vec2(-1.0, 1.0), vec2(-1.0, -1.0), vec2(1.0, -1.0) };
	vec2 mult_base = vec2(1.0, 0.0);
	for (int o = 0; o < 4; ++o) {
		vec2 offset = offsets[o]/size;
		vec2 mult = mult_base;
		for (int d = 0; d < 2; ++d) {
			vec2 uv2 = uv;
			int l = 0;
			for (int i = 1; i < iterations; i += 1) {
				vec2 uv2_save = uv2;
				uv2 += offset*mult;
				vec4 color2 = $in(fract(uv2));
				if (color2.z+color2.w == 0.0) {
					if (l < 1) {
						mult = mult.yx;
						l += 1;
						uv2 = uv2_save;
						continue;
					}
					break;
				}
				l = 0;
				vec2 p1 = color.xy+floor(uv-color.xy);
				vec2 p2 = color2.xy+floor(uv2-color2.xy);
				vec2 p = min(p1, p2);
				vec2 s = max(p1+color.zw, p2+color2.zw)-p;
				color = mix(vec4(0.0, 0.0, 1.0, 1.0), vec4(fract(p), s), step(s.xyxy, vec4(1.0)));
