shader_model.instance:
vec4 $(name)_fct(vec2 uv) {
	float e = 1.0/$size;
	vec4 rv = vec4(0.0);
	float sum = 0.0;
	float sigma = max(0.000001, $sigma*$amount(uv));
	for (float i = -50.0; i <= 50.0; i += 1.0) {
		float coef = exp(-0.5*(pow(i/sigma, 2.0)))/(6.28318530718*sigma*sigma);
		rv += $in(uv+vec2(i*e, 0.0))*coef;
		sum += coef;
	}
	return rv/sum;
}

vec4 $(name)_fct(vec2 uv) {
	float e = 1.0/$size;
	//range based on 68–95–99.7 rule
	float scaled_sigma = $sigma /10.0;
	float sampling_range = scaled_sigma*3.0;
	vec4 rv = vec4(0.0);
	float sum = 0.0;
	float sigma = max(0.000015, scaled_sigma*$amount(uv));
	float mapped_quality = 1.0 + ($quality - 1.0) * ($size - 1.0) / (100.0 - 1.0);

	float step_size = max(e,1.0/mapped_quality);
	//maxium number of loop iterations = 1024
	step_size = max(sampling_range*2.0/1024.0,step_size);
	step_size -= mod(step_size, e);
	float coef_diff = 6.28318530718*sigma*sigma;
	for (float i = -sampling_range; i <= sampling_range; i += step_size) {
		float i_sigma = i/sigma;
		float coef = exp(-0.5*i_sigma*i_sigma)/coef_diff;
		rv += $in(uv+vec2(i, 0.0))*coef;
		sum += coef;
	}
	return rv/sum;
}

