// MIT License - Garrett Gunnell
// Based on https://github.com/GarrettGunnell/Post-Processing/blob/main/Assets/Kuwahara%20Filter/GeneralizedKuwahara.shader
vec3 $(name)_generalized_kuwahara(vec2 uv, int _KernelSize) {
	vec4 m[8];
	vec3 s[8];

	int kernelRadius = _KernelSize;

	float zeta = 2.0 / float(kernelRadius);
	const float _Q = 18.0;
	const float zeroCross = 2.0;

	float sinZeroCross = sin(zeroCross);
	float eta = (zeta + cos(zeroCross)) / (sinZeroCross * sinZeroCross);

	for (int k = 0; k < 8; ++k) {
		m[k] = vec4(0.0);
		s[k] = vec3(0.0);
	}

	for (int y = -kernelRadius; y <= kernelRadius; ++y) {
		for (int x = -kernelRadius; x <= kernelRadius; ++x) {
			vec2 v = vec2(float(x), float(y)) / float(kernelRadius);
			vec3 c = $in(uv + vec2(float(x), float(y)) * 1.0/$s);
			c = clamp(c,vec3(0.0),vec3(1.0));
			float sum = 0.0;
			float w[8];
			float z, vxx, vyy;

			vxx = zeta - eta * v.x * v.x;
			vyy = zeta - eta * v.y * v.y;
			z = max(0, v.y + vxx); 
			w[0] = z * z;
			sum += w[0];
			z = max(0, -v.x + vyy); 
			w[2] = z * z;
			sum += w[2];
			z = max(0, -v.y + vxx); 
			w[4] = z * z;
			sum += w[4];
			z = max(0, v.x + vyy); 
			w[6] = z * z;
			sum += w[6];
			v = sqrt(2.0) / 2.0 * vec2(v.x - v.y, v.x + v.y);
			vxx = zeta - eta * v.x * v.x;
			vyy = zeta - eta * v.y * v.y;
			z = max(0, v.y + vxx); 
			w[1] = z * z;
			sum += w[1];
			z = max(0, -v.x + vyy); 
			w[3] = z * z;
			sum += w[3];
			z = max(0, -v.y + vxx); 
			w[5] = z * z;
			sum += w[5];
			z = max(0, v.x + vyy); 
			w[7] = z * z;
			sum += w[7];

			float g = exp(-3.125 * dot(v,v)) / sum;

		   for (int k = 0; k < 8; ++k) {
				float wk = w[k] * g;
				m[k] += vec4(c * wk, wk);
				s[k] += c * c * wk;
		   }
		}
	}

	vec4 o = vec4(0.0);
	  for (int k = 0; k < 8; ++k) {
		m[k].rgb /= m[k].w;
		s[k] = abs(s[k] / m[k].w - m[k].rgb * m[k].rgb);

		float sigma2 = s[k].r + s[k].g + s[k].b;
		float w = 1.0 / (1.0 + pow(1000.0 * sigma2, 0.5 * _Q));

		o += vec4(m[k].rgb * w, w);
	}
	return clamp(o / o.w,vec4(0.0),vec4(1.0)).rgb;
}

