//  
//  https://github.com/BrutPitt/glslSmartDeNoise/
//
//  This software is distributed under the terms of the BSD 2-Clause license
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
//  smartDeNoise - parameters
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
//
//  sampler2D tex	 - sampler image / texture
//  vec2 uv		   - actual fragment coord
//  float sigma  >  0 - sigma Standard Deviation
//  float kSigma >= 0 - sigma coefficient 
//	  kSigma * sigma  -->  radius of the circular kernel
//  float threshold   - edge sharpening threshold 
vec4 $(name)_smartDeNoise(vec2 uv, float sigma, float kSigma, float threshold)
{
	float INV_SQRT_OF_2PI = 0.39894228040143267793994605993439; // 1.0/SQRT_OF_2PI
	float INV_PI = 0.31830988618379067153776752674503;
	float radius = round(kSigma*sigma);
	float radQ = radius * radius;

	float invSigmaQx2 = .5 / (sigma * sigma);	  // 1.0 / (sigma^2 * 2.0)
	float invSigmaQx2PI = INV_PI * invSigmaQx2;	// 1/(2 * PI * sigma^2)

	float invThresholdSqx2 = .5 / (threshold * threshold);	 // 1.0 / (sigma^2 * 2.0)
	float invThresholdSqrt2PI = INV_SQRT_OF_2PI / threshold;   // 1.0 / (sqrt(2*PI) * sigma^2)

	vec4 centrPx = $in(uv); 

	float zBuff = 0.0;
	vec4 aBuff = vec4(0.0);
	vec2 size = vec2($size, $size);

	vec2 d;
	for (d.x=-radius; d.x <= radius; d.x++) {
		float pt = sqrt(radQ-d.x*d.x);	   // pt = yRadius: have circular trend
		for (d.y=-pt; d.y <= pt; d.y++) {
			float blurFactor = exp( -dot(d , d) * invSigmaQx2 ) * invSigmaQx2PI;

			vec4 walkPx =  $in(uv+d/size);
			vec4 dC = walkPx-centrPx;
			float deltaFactor = exp( -dot(dC, dC) * invThresholdSqx2) * invThresholdSqrt2PI * blurFactor;

			zBuff += deltaFactor;
			aBuff += deltaFactor*walkPx;
		}
	}
	return aBuff/zBuff;
}

shader_model.global:
vec4 hbl_adjust_levels(vec4 i, vec4 in_min, vec4 in_mid, vec4 in_max, vec4 out_min, vec4 out_max) {
	i = clamp((i-in_min)/(in_max-in_min), 0.0, 1.0);
	in_mid = (in_mid-in_min)/(in_max-in_min);
	vec4 dark = step(in_mid, i);
	i = 0.5*mix(i/(in_mid), 1.0+(i-in_mid)/(1.0-in_mid), dark);
	return out_min+i*(out_max-out_min);
}

shader_model.instance:
float $(name)_fct(vec2 uv, float epsilon) {
	vec3 e = vec3(epsilon, -epsilon, 0);
	float start = $in(uv);
	vec2 dh = vec2(1.0, 0.0)*$in(uv+e.xz);
	dh += vec2(0.0, 1.0)*$in(uv+e.zx);
	dh -= vec2(1.0, 0.0)*$in(uv-e.xz);
	dh -= vec2(0.0, 1.0)*$in(uv-e.zx);
	return atan(dh.y, dh.x)/3.141592;
}

vec2 $(name)_fct(vec2 uv, float target, float epsilon) {
	vec3 e = vec3(epsilon, -epsilon, 0);
	float start = $in(uv);
	vec2 dh = vec2(1.0, 0.0)*$in(uv+e.xz);
	dh += vec2(0.0, 1.0)*$in(uv+e.zx);
	dh -= vec2(1.0, 0.0)*$in(uv-e.xz);
	dh -= vec2(0.0, 1.0)*$in(uv-e.zx);
	dh /= 2.0*epsilon;
	return 16.0*dh/dot(dh,dh)*(target-start);
}

shader_model.global:
float IChing(vec2 uv, float seed) {
	int value = int(32.0*rand(floor(uv)+vec2(seed)));
	float base = step(0.5, fract(fract(uv.y)*6.5))*step(0.04, fract(uv.y+0.02))*step(0.2, fract(uv.x+0.1));
	int bit = int(fract(uv.y)*6.5);
	return base*step(0.1*step(float(bit & value), 0.5), fract(uv.x+0.55));
}

shader_model.instance:
float iterate_variations_$(name)(vec2 uv, float v1, float v2, float step) {
	float v = 0.0;
	if (sign(step) == sign(v2-v1)) {
		float count = 1.0+floor((v2-v1)/step);
		float seedvar = _seed_variation_;
		vec4 var = _controlled_variation_;
		var.$variable = v1;
		float input_v = $in.variation(uv, _seed_variation_, var);
		v = $combine;
		for (float x = v1+step; x < v2; x += step) {
			var.$variable = x;
			input_v = $in.variation(uv, seedvar, var);
			v = $combine;
			if ($randomize) {
				seedvar = rand(vec2(seedvar,x));
			}
		}
	}
	return v;
}

shader_model.global:
vec3 old_kal_rotate(vec2 uv, float count, float offset, float seed) {
	float pi = 3.14159265359;
	offset *= pi/180.0;
	offset += pi*(1.0/count+0.5);
	uv -= vec2(0.5);
	float l = length(uv);
	float angle = atan(uv.y, uv.x)+offset;
	angle += (1.0-sign(angle))*pi;
	float a = mod(angle, 2.0*pi/count)-offset;
	return vec3(vec2(0.5)+l*vec2(cos(a), sin(a)), rand(vec2(seed))+floor(0.5*angle*count/pi));
}

vec3 kal_rotate(vec2 uv, float count, float offset, float seed) {
	float pi = 3.14159265359;
	offset *= pi/180.0;
	offset += pi*(1.0/count+0.5);
	uv -= vec2(0.5);
	float l = length(uv);
	float angle = atan(uv.y, uv.x)+offset;
	angle += (1.0-sign(angle))*pi;
	float a = mod(angle, 2.0*pi/count)-offset;
	return vec3(vec2(0.5)+l*vec2(cos(a), sin(a)), (rand(vec2(seed))+floor(0.5*angle*count/pi))/count);
}

shader_model.instance:
float layer_variations_$(name)(vec2 uv, float v1, float v2, float step) {
	float v = 0.0;
	if (sign(step) == sign(v2-v1)) {
		float count = 1.0+floor((v2-v1)/step);
		float seedvar = _seed_variation_;
		vec4 var = _controlled_variation_;
		var.$variable = v1;
		float input_v = $in.variation(uv, seedvar, var);
		v = input_v;
		for (float x = v1+step; x < v2; x += step) {
			var.$variable = x;
			input_v = $in.variation(uv, seedvar, var);
			float mask_v = $mask.variation(uv, seedvar, var);
			v = mix(v, input_v, mask_v);
			if ($randomize) {
				seedvar = rand(vec2(seedvar,x));
			}
		}
	}
	return v;
}

vec4 layer_variations_$(name)(vec2 uv, float v1, float v2, float step) {
	vec4 v = vec4(0.0);
	if (sign(step) == sign(v2-v1)) {
		float count = 1.0+floor((v2-v1)/step);
		float seedvar = _seed_variation_;
		vec4 var = _controlled_variation_;
		var.$variable = v1;
		vec4 input_v = $in.variation(uv, seedvar, var);
		v = input_v;
		for (float x = v1+step; x < v2; x += step) {
			var.$variable = x;
			input_v = $in.variation(uv, seedvar, var);
			v = vec4(mix(v.rgb, input_v.rgb, input_v.a), min(1.0, input_v.a+v.a));
			if ($randomize) {
				seedvar = rand(vec2(seedvar,x));
			}
		}
	}
	return v;
}

vec4 make_tileable_$(name)(vec2 uv, float w) {
	vec4 a = $in(uv);
	vec4 b = $in(fract(uv+vec2(0.5)));
	float coef_ab = sin(1.57079632679*clamp((length(uv-vec2(0.5))-0.5+w)/w, 0.0, 1.0));
	vec4 c = $in(fract(uv+vec2(0.25)));
	float coef_abc = sin(1.57079632679*clamp((min(min(length(uv-vec2(0.0, 0.5)), length(uv-vec2(0.5, 0.0))), min(length(uv-vec2(1.0, 0.5)), length(uv-vec2(0.5, 1.0))))-w)/w, 0.0, 1.0));
	return mix(c, mix(a, b, coef_ab), coef_abc);
}

