uniform sampler2D texture_albedo : source_color; // $output(0)
uniform sampler2D texture_emission : hint_default_black; // $output(2)
uniform sampler2D texture_normal : hint_normal; // $output(3)
uniform sampler2D texture_orm : hint_default_white; // $output(1)
uniform sampler2D texture_subsurface_scattering : hint_default_white; // $output(5)
uniform sampler2D texture_depth : hint_default_black; // $output(4)
uniform int depth_min_layers = 64;
uniform int depth_max_layers = 64;
uniform vec2 depth_flip = vec2(1.0);

uniform vec3 uv1_scale;
uniform vec3 uv1_offset;

$definitions

void vertex() {
	UV=UV*uv1_scale.xy+uv1_offset.xy;
}

void fragment() {
	vec2 base_uv = UV;
	int texture_size = textureSize(texture_albedo, 0).x;
	if (texture_size < 256) {
		base_uv = floor(float(texture_size)*base_uv+0.5)/float(texture_size);
	}
$if $(connected:depth_tex)
	{
$begin_generate
		float depth_scale = 0.2*$depth_scale;
$end_generate
		vec3 view_dir = normalize(normalize(-VERTEX)*mat3(TANGENT*depth_flip.x,-BINORMAL*depth_flip.y,NORMAL));
		float num_layers = mix(float(depth_max_layers),float(depth_min_layers), abs(dot(vec3(0.0, 0.0, 1.0), view_dir)));
		float layer_depth = 1.0 / num_layers;
		float current_layer_depth = 0.0;
		vec2 P = view_dir.xy * depth_scale;
		vec2 delta = P / num_layers / dot(VIEW, NORMAL);
		vec2  ofs = base_uv;
		float depth = textureLod(texture_depth, ofs,0.0).r;
		float current_depth = 0.0;
		while(current_depth < depth) {
			ofs -= delta;
			depth = textureLod(texture_depth, ofs,0.0).r;
			current_depth += layer_depth;
		}
		vec2 prev_ofs = ofs + delta;
		float after_depth  = depth - current_depth;
		float before_depth = textureLod(texture_depth, prev_ofs, 0.0).r - current_depth + layer_depth;
		float weight = after_depth / (after_depth - before_depth);
		ofs = mix(ofs,prev_ofs,weight);
		base_uv=ofs;
	}
$fi
$begin_generate
	vec4 albedo_tex = texture(texture_albedo, base_uv);
	ALBEDO = $albedo_color.rgb * mix(pow((albedo_tex + vec4(0.055))/vec4(1.055), vec4(2.4)), albedo_tex/vec4(12.92), lessThan(albedo_tex, vec4(0.04045))).rgb;
	vec4 orm_tex = texture(texture_orm, base_uv);
	METALLIC = $metallic*orm_tex.b;
	ROUGHNESS = $roughness*orm_tex.g;
	SPECULAR = 0.5;
	NORMAL_MAP = texture(texture_normal, base_uv).rgb;
	NORMAL_MAP_DEPTH = $normal;
	vec3 emission_tex = texture(texture_emission, base_uv).rgb;
	EMISSION = emission_tex*$emission_energy;
	AO = orm_tex.r;
	AO_LIGHT_AFFECT = $ao;
$if $(connected:opacity_tex) and $(param:flags_transparent)
	ALPHA = albedo_tex.a;
$fi
$if $(connected:sss_tex)
	float sss_tex = texture(texture_subsurface_scattering, base_uv).r;
	SSS_STRENGTH=$sss*sss_tex;
$fi
$end_generate
}

