vec2 GetDist(vec3 p) {
	float _seed_variation_ = 0.0;
	vec4 _controlled_variation_ = vec4(0.0);

$begin_generate
		if ($flip_y) {
			p *= vec3(1.0, -1.0, 1.0);
		} 
$end_generate
$begin_generate
	vec2 d = $distance(p);
$end_generate

	return d;
}

vec2 RayMarch(vec3 ro, vec3 rd) {
	float dO = 0.0;
	float color = 0.0;
	vec2 dS;

	for (int i = 0; i < MAX_STEPS; i++)
	{
		vec3 p = ro + dO * rd;
		dS = GetDist(p);
		dO += dS.x;

		if (abs(dS.x) < SURF_DIST || dO > MAX_DIST) {
			color = dS.y;
			break;
		}
	}
	return vec2(dO, color);
}

vec3 GetNormal(vec3 p) {
	vec2 e = vec2(1e-3, 0);

	vec3 n = GetDist(p).x - vec3(
		GetDist(p - e.xyy).x,
		GetDist(p - e.yxy).x,
		GetDist(p - e.yyx).x
	);

	return normalize(n);
}

