	float _seed_variation_ = 0.0;
	vec4 _controlled_variation_ = vec4(0.0);
	vec3 ro = world_camera;
	vec3 rd =  normalize(world_position - ro);

	vec2 rm  = RayMarch(ro, rd);
	float d = rm.x;

	if (d >= MAX_DIST)
		discard;
	else
	{
		vec3 p = ro + rd * d;
		vec3 n = GetNormal(p);
