float pingpong(float a, float b)
{
  return (b != 0.0) ? abs(fract((a - b) / (b * 2.0)) * b * 2.0 - b) : 0.0;
}

float mesh_capsule(vec2 uv) {
	uv = uvmirror_h(uv, 0.25, 1.0);
	return sin((1.0 - length(vec2(0.5) - uv) / .25) * 1.57);
}

float mesh_ridged_bell(vec2 uv) {
	uv = scale(uv, vec2(0.5), vec2(0.9, 0.5));
	uv = transform2_clamp(uv);
	float triangle = min(uv.y, 1.0 - uv.y) * 2.0;
	triangle = 1.0 - sqrt(1.0 - pow(triangle, 2.0));
	float sine = 0.5 - 0.5 * cos(uv.x * 3.14159265359 * 2.0);
	return triangle * sine;
}

float mesh_screen_blend(float back, float fore) {
	return 1.0 - (1.0 - back) * (1.0 - fore);
}

