vec3 $(name)_mesh_pattern(vec2 uv) {
	uv *= $tiling;
	if ($diagonal) {
		uv = transform2(uv, vec2(0.0), 45.0 * 0.01745329251, vec2(1.0 / sqrt(2.0)));
	}

	float pattern = 0.0;
	float mask = 0.0;

	if ($shape == 0) {
		pattern = max(pattern, mesh_ridged_bell(fract(uv + vec2(0.5, 0.0))));
		pattern = max(pattern, mesh_ridged_bell(fract(uv + vec2(0.0, 0.5))));
		float pattern2 = mesh_ridged_bell(fract(uv.yx));
		pattern2 = max(pattern2, mesh_ridged_bell(fract(uv.yx + vec2(0.5, 0.5))));
		mask = float(pattern > pattern2);
		pattern = mesh_screen_blend(pattern, pattern2);
	} else if($shape == 1) {
		pattern = max(pattern, mesh_capsule(fract(uv + vec2(0.5, 0.0))));
		pattern = max(pattern, mesh_capsule(fract(uv + vec2(0.0, 0.5))));
		float pattern2 = mesh_capsule(fract(uv.yx));
		pattern2 = max(pattern2, mesh_capsule(fract(uv.yx + vec2(0.5, 0.5))));
		mask = float(pattern > pattern2);
		pattern = max(pattern, pattern2);
	} else if($shape == 2) {
		pattern = max(pattern, $in(fract(uv + vec2(0.5, 0.0))));
		pattern = max(pattern, $in(fract(uv + vec2(0.0, 0.5))));
		float pattern2 = $in(fract(uv.yx));
		pattern2 = max(pattern2, $in(fract(uv.yx + vec2(0.5, 0.5))));
		mask = float(pattern > pattern2);
		pattern = max(pattern, pattern2);
	}
	return vec3(pattern, mask, 1.0 - mask);
