float curvature_$(name)(vec2 uv, float epsilon) {
	vec2 eps = vec2(epsilon, 0.0);
	vec3 dp;
	dp = $position(uv+eps)-$position(uv-eps);
	float curvature = length($normal(uv+eps)-$normal(uv-eps))/max(epsilon, length(dp));
	dp = $position(uv+eps)-$position(uv-eps);
	curvature = max(curvature, length($normal(uv+eps.yx)-$normal(uv-eps.yx))/max(epsilon, length(dp)));
	return curvature;
}

float curvature2_$(name)(vec2 uv, float epsilon) {
	vec2 eps = vec2(epsilon, 0.0);
	vec3 dp;
	dp = $position(uv+eps)-$position(uv-eps);
	float curvature = dot($normal(uv+eps)-$normal(uv-eps), dp);
	dp = $position(uv+eps.yx)-$position(uv-eps.yx);
	curvature = curvature+dot($normal(uv+eps.yx)-$normal(uv-eps.yx), dp);
