float multigradient(vec2 uv, int count, float seed) {
	float rv = 1.0;
	float angle = 0.0;
	for (int i = 0; i < count; ++i) {
		angle = rand(vec2(seed, angle))*6.28;
		float v = 0.5+(cos(angle)*(uv.x-0.5)+sin(angle)*(uv.y-0.5))/(cos(abs(mod(angle, 0.5*3.141592)-0.25*3.141592))*1.41421356237);
		rv = min(rv, v);
	}
	return rv;
}

vec2 matmap_uv(vec2 uv, float angle, float seed) {
	uv -= vec2(0.5);
	vec2 rv;
	rv.x = uv.x*cos(angle)+uv.y*sin(angle);
	rv.y = -uv.x*sin(angle)+uv.y*cos(angle);
	return fract(rv + rand2(vec2(seed)));
}

vec3 matmap_rotate_nm(vec3 input_nm, float angle) {
	vec2 uv = input_nm.xy - vec2(0.5);
	vec2 rv;
	rv.x = uv.x*cos(angle)+uv.y*sin(angle);
	rv.y = -uv.x*sin(angle)+uv.y*cos(angle);
	return vec3(rv + vec2(0.5), input_nm.z);
}

