vec3 nm_compare_$name(vec2 uv, float amount, float size) {
	vec3 e = vec3(1.0/size, -1.0/size, 0);
	vec2 rv;
	rv = vec2(1.0, -1.0)*$in(uv+e.xy);
	rv += vec2(-1.0, 1.0)*$in(uv-e.xy);
	rv += vec2(1.0, 1.0)*$in(uv+e.xx);
	rv += vec2(-1.0, -1.0)*$in(uv-e.xx);
	rv += vec2(2.0, 0.0)*$in(uv+e.xz);
	rv += vec2(-2.0, 0.0)*$in(uv-e.xz);
	rv += vec2(0.0, 2.0)*$in(uv+e.zx);
	rv += vec2(0.0, -2.0)*$in(uv-e.zx);
	rv *= size*40.0/amount/128.0;
	return vec3(0.5)+0.5*normalize(vec3(rv, -1.0));
}

float height_$name(vec2 uv) {
	float height = 0.0;
	float sum = 0.0;
	for (int dx = -5; dx <= 5; ++dx) {
		for (int dy = -5; dy <= 5; ++dy) {
			vec2 d = vec2(float(dx), float(dy));
			vec2 p = uv+d/$size;
			float h = $h(p);
			float w = max(1.0-50.0*$q(p), 0.01)/(1.0+dot(d,d));
			h -= $scale*dot(d/$size, $nm(p).xy-vec2(0.5));
			height += w*h;
			sum += w;
		}
	}
	return height/sum;
}

float find_height_$name(vec2 uv, vec2 center, float center_height, int steps) {
	vec2 p;
	float height = center_height;
	float sum = 0.0;
	for (int i = 0; i < steps; ++i) {
		p = mix(center, uv, float(i)/float(steps));
		vec2 nm = $nm(p).xy-vec2(0.5);
		height += $scale*dot((uv-center)/float(steps), nm);
	}
	return height;
}

float height_$name(vec2 uv) {
	const vec2 c = vec2(0.5);
	float center_height = $center_height;
	float l = length(uv-c)*$size;
	float lx = abs(uv.x-c.x)*$size;
	float ly = abs(uv.y-c.y)*$size;
	float h = find_height_$name(uv, c, center_height, int(l)+1);
	float hxi = find_height_$name(vec2(c.x, uv.y), c, center_height, int(ly)+1);
	float hx = find_height_$name(uv, vec2(c.x, uv.y), hxi, int(lx)+1);
	float hyi = find_height_$name(vec2(uv.x, c.y), c, center_height, int(lx)+1);
	float hy = find_height_$name(uv, vec2(uv.x, c.y), hyi, int(ly)+1);
	return 0.5*h+0.25*(hx+hy);
}

