	rv += vec2(-1.0, -1.0)*$in(uv-e.xx);
	rv += vec2(2.0, 0.0)*$in(uv+e.xz);
	rv += vec2(-2.0, 0.0)*$in(uv-e.xz);
	rv += vec2(0.0, 2.0)*$in(uv+e.zx);
