vec3 nm_$name(vec2 uv, float amount, float size) {
	vec3 e = vec3(1.0/size, -1.0/size, 0);
	vec2 rv;
	if ($algo == 0) {
		rv = vec2(1.0, -1.0)*$in(uv+e.xy);
		rv += vec2(-1.0, 1.0)*$in(uv-e.xy);
		rv += vec2(1.0, 1.0)*$in(uv+e.xx);
		rv += vec2(-1.0, -1.0)*$in(uv-e.xx);
		rv += vec2(2.0, 0.0)*$in(uv+e.xz);
		rv += vec2(-2.0, 0.0)*$in(uv-e.xz);
		rv += vec2(0.0, 2.0)*$in(uv+e.zx);
		rv += vec2(0.0, -2.0)*$in(uv-e.zx);
		rv *= size*amount/128.0;
	} else if ($algo == 1) {
		rv = vec2(3.0, -3.0)*$in(uv+e.xy);
		rv += vec2(-3.0, 3.0)*$in(uv-e.xy);
		rv += vec2(3.0, 3.0)*$in(uv+e.xx);
		rv += vec2(-3.0, -3.0)*$in(uv-e.xx);
		rv += vec2(10.0, 0.0)*$in(uv+e.xz);
		rv += vec2(-10.0, 0.0)*$in(uv-e.xz);
		rv += vec2(0.0, 10.0)*$in(uv+e.zx);
		rv += vec2(0.0, -10.0)*$in(uv-e.zx);
		rv *= size*amount/512.0;
	} else if ($algo == 2) {
		rv = vec2(2.0, 0.0)*$in(uv+e.xz);
		rv += vec2(-2.0, 0.0)*$in(uv-e.xz);
		rv += vec2(0.0, 2.0)*$in(uv+e.zx);
		rv += vec2(0.0, -2.0)*$in(uv-e.zx);
		rv *= size*amount/64.0;
	} else {
		rv = vec2(1.0, 0.0)*$in(uv+e.xz);
		rv += vec2(0.0, 1.0)*$in(uv+e.zx);
		rv += vec2(-1.0, -1.0)*$in(uv);
		rv *= size*amount/20.0;
	}
	return vec3(0.5)+0.5*normalize(vec3(rv, -1.0));
}

vec4 $(name)_blur(vec2 uv, vec2 scale, float sigma, int quality) {
	vec4 O = vec4(0.0);
	float samples = sigma * 4.0; 
	int LOD = max(0, int(log2(float(samples)))-quality-2);
	int sLOD = 1 << LOD;
	int s = max(1, int(samples/float(sLOD)));
	float sum = 0.0;
	for (int i = 0; i < s*s; i++) {
		vec2 d = vec2(float(i%s), float(i/s))*float(sLOD) - 0.5*float(samples);
		vec2 dd = d / sigma;
		float g = exp(-.5*dot(dd,dd))/(6.28*sigma*sigma);
		O += g * textureLod($in.texture, uv + scale * d, float(LOD));
		sum += g;
	}

	return O / sum;
}

