vec3 find_color_from_palette_$name(vec3 color, int size) {
	float min_dist = 10.0;
	vec3 best_color = vec3(0.0);
	for (int i = 0; i < size; ++i) {
		float x = (float(i)+0.5)/float(size);
		for (int j = 0; j < size; ++j) {
			float y = (float(j)+0.5)/float(size);
			vec3 c = $palette(vec2(x, y));
			float l = length(color - c);
			if (l < min_dist) {
				min_dist = l;
				best_color = c;
			}
		}
	}
	return best_color;
}

