shader_model.global:
vec2 curve(float t, vec2 a, vec2 b, vec2 c, vec2 d) {
	vec2 e = c-b;
	vec2 f = a-d;
	vec2 g = a-b;
	return (b+0.5*t*(e-g+t*(g+e+t*3.0*(e*3.0+f+t*5.0/3.0*(-e*3.0-f+t*0.4*(e*3.0+f))))));
}

vec2 dcurve(float t, vec2 a, vec2 b, vec2 c, vec2 d) {
	vec2 e = c-b;
	vec2 f = a-d;
	vec2 g = a-b;
	return 0.5*((((f+3.0*e)*((10.0*t-20.0)*t+9.0))*t+2.0*(g+e))*t+e-g);
}
vec2 solve_cubic(vec2 uv, vec2 a, vec2 b, vec2 c, vec2 d) {
	float t = 0.5;
	vec2 pos, dv;
	float current_sign = 0.0;
	float dt = 0.25;
	for (int i = 0; i < 20; ++i) {
		pos = curve(t, a, b, c, d);
		dv = dcurve(t, a, b, c, d);
		float new_sign = sign(dot(normalize(uv - pos), dv));
		if (new_sign != current_sign) {
			current_sign = new_sign;
			dt *= 0.5;
		}
		t += dt*current_sign;
	}
	t = clamp(t, 0.0, 1.0);
	return vec2(t, length(uv-curve(t, a, b, c, d)));
}

shader_model.instance:
vec2 bezier_uv_$name(vec2 uv, bool ends) {	
	vec2 v[] = $curve;
	int l = v.length();
	vec2 best_bezier;
	if (ends) {
		best_bezier = solve_cubic(uv, v[0], v[0], v[1], v[2]);
	} else {
		best_bezier = vec2(0.0, 10000.0);
	}
	float offset = 0.0;
	for (int i = 0; i < l-3; i++) {
		vec2 bezier = solve_cubic(uv, v[i], v[i+1], v[i+2], v[i+3]);
		if (abs(bezier.y) < abs(best_bezier).y) {
			best_bezier = bezier;
			offset = float(i)+1.0;
		}
	}
	float width;
	float offset_min;
	float offset_max;
	if (ends) {
		vec2 bezier = solve_cubic(uv, v[l-3], v[l-2], v[l-1], v[l-1]);
		if (abs(bezier.y) < abs(best_bezier).y) {
			best_bezier = bezier;
			offset = float(l-2);
		}
		width = $width*$width_map(vec2((best_bezier.x+offset)/float(l-1), 0.0));
		offset_min = 0.0;
		offset_max = float(l-2);
	} else {
		width = $width*$width_map(vec2((best_bezier.x+offset-1.0)/float(l-3), 0.0));
		offset_min = 1.0;
		offset_max = float(l-3);
	}
	vec2 local_uv = vec2(best_bezier.x, best_bezier.y/width+0.5);
	vec2 uvtest = vec2(0.0);
	if (offset <= offset_min && local_uv.x <= 0.0 || offset >= offset_max && local_uv.x >= 1.0) {
		uvtest = step(vec2(0.5), abs(local_uv-vec2(0.5)));
	}
	return mix(vec2(fract($repeat*local_uv.x), local_uv.y), vec2(0.0), max(uvtest.x, uvtest.y));
}

