float draw_profile_fill(vec2 uv, float y, float dy, float w) {
	return 1.0-clamp(sin(1.57079632679-atan(dy))*(1.0-uv.y-y)/w, 0.0, 1.0);
}

float draw_profile_curve(vec2 uv, float y, float dy, float w) {
	return 1.0-clamp(sin(1.57079632679-atan(dy))*abs(1.0-uv.y-y)/w, 0.0, 1.0);
}

shader_model.instance:
vec2 raymarch_$name(vec2 uv) {
	vec3 ro = vec3(uv-vec2(0.5), 1.0);
	vec3 rd = vec3(0.0, 0.0, -1.0);
	float dO = 0.0;
	float c = 0.0;
	for (int i=0; i < 100; i++) {
		vec3 p = ro + rd*dO;
		vec2 dS = $sdf(p);
		dO += dS.x;

		if (dO >= 1.0) {
			break;
		} else if (abs(dS.x) < 0.0001) {
			c = dS.y;
			break;
		}
	}

	return vec2(dO, c);
}

vec3 normal_$name(vec3 p) {
	if (p.z <= 0.0) {
		return vec3(0.0, 0.0, -1.0);
	}

	float d = $sdf(p).x;
	float e = .001;

	vec3 n = d - vec3(
		$sdf(p-vec3(e, 0.0, 0.0)).x,
		$sdf(p-vec3(0.0, e, 0.0)).x,
		$sdf(p-vec3(0.0, 0.0, e)).x);

	return vec3(-1.0, -1.0, -1.0)*normalize(n);
}

float calcdist_$name(vec3 p) {
	return min($sdf(p), p.z);
}

float raymarch_$name(vec3 ro, vec3 rd) {
	float d=0.0;
	for (int i = 0; i < 50; i++) {
		vec3 p = ro + rd*d;
		float dstep = calcdist_$name(p);
		d += dstep;
		if (dstep < 0.0001) break;
	}
	return d;
}

vec3 normal_$name(vec3 p) {
	float d = calcdist_$name(p);
	float e = .0001;
	vec3 n = d - vec3(calcdist_$name(p-vec3(e, 0.0, 0.0)), calcdist_$name(p-vec3(0.0, e, 0.0)), calcdist_$name(p-vec3(0.0, 0.0, e)));
	return normalize(n);
}

vec3 render_$name(vec2 uv) {
	vec3 p = vec3(uv, 2.0-raymarch_$name(vec3(uv, 2.0), vec3(0.0, 0.0, -1.0)));
	vec3 n = normal_$name(p);
	vec3 l = vec3(5.0, 5.0, 10.0);
	vec3 ld = normalize(l-p);
	float o = step(p.z, 0.001);
	float shadow = 1.0-0.75*step(raymarch_$name(l, -ld), length(l-p)-0.01);
	float light = 0.3+0.7*dot(n, ld)*shadow;
	return vec3(0.8+0.2*o, 0.8+0.2*o, 1.0)*light;
}

vec2 $(name)_refract(vec2 uv, float refract) {
	vec2 eps = vec2(0.001, 0.0);
	vec3 n = normalize(vec3($s(uv+eps)-$s(uv-eps), $s(uv+eps.yx)-$s(uv-eps.yx), -10.0*eps.x));
	float h = $s(uv);
	vec3 i = vec3(0.0, 0.0, -1.0);
	float mu = 1.0/refract;

	float dot_n_i = dot(n, i);
	vec3 t = sqrt(max(0.0, 1.0-mu*mu*(1.0-dot_n_i*dot_n_i)))*n+mu*(i-dot_n_i*n);

	return uv+h*t.xy/t.z;
}

shader_model.global:
float line(vec2 p, vec4 l) { return sdLine(p,l.xy,l.zw).x; }

float ri(vec2 p, float w, float h)
{
	float d = line(abs(p), vec4(w*1.7,h,0,h));
	return min(d,line(vec2(p.x,abs(p.y)), vec4(0,h,0,0)));
}

float rv(vec2 p, float w, float h)
{
	p.x = abs(p.x);
	float d = line(p,vec4(0,h,w,-h));
	return min(d,line(vec2(abs(p.x-w),p.y+h), vec4(w*0.8,0,0,0)));
}

float rx(vec2 p, float w, float h)
{
	p = abs(p);
	float d = line(p,vec4(w,h,0,0));
	return min(d, line(abs(p-vec2(w,h)),vec4(w*0.8,0,0,0)));
}

float rl(vec2 p, float w, float h)
{
	float w2 = w*1.5;
	float d = line(p,vec4(-w2,h,-w2,-h));
	return min(d, line(p,vec4(-w2,h,w2,h)));
}

float rnum(vec2 p,float w, float h, float s, int n)
{
	vec2 s0 = vec2(s,0);
	float rn[6] = float[] (
			min(rx(p,w,h),rl(p-s0,w,h)),
			rx(p,w,h),
			min(ri(p,w,h),rx(p-s0,w,h)),
			rv(p,w,h),
			min(ri(p,w,h),rv(p-s0,w,h)),
			ri(p,w,h) );
	return rn[n];
}

float roman(vec2 p, float w, float h, int n, float bevel, float r, float s)
{
	p -= 0.5;
	h *= 0.5;
	w *= 0.25;
	const int val[] = {40,10,9,5,4,1};
	float res = 1.0; n = clamp(n,0,40);

	for (int i = 0; i < 6; ++i) {
		while(n - val[i] >= 0) {
			float no = rnum(p,w,h,s,i);
			res = min(res,no);
			p -= vec2(s,0);
			n -= val[i]; 
		}}
	return clamp(0.0-(res-r*0.03)/max(bevel, 1e-4), 0, 1);
}

float roman2_num(vec2 p, float w, float h, float s, int n) {
	if (n == 0) { // I
		float d = sdLine(abs(p), vec2(w*1.7,h), vec2(0,h)).x;
		return min(d,sdLine(vec2(p.x,abs(p.y)), vec2(0,h), vec2(0,0)).x);
	} else if (n == 1) { // V
		p.x = abs(p.x);
		float d = sdLine(p, vec2(0,h), vec2(w,-h)).x;
		return min(d, sdLine(vec2(abs(p.x-w),p.y+h), vec2(w*0.8,0), vec2(0,0)).x);
	} else if (n == 2) { // X
		p = abs(p);
		float d = sdLine(p, vec2(w,h), vec2(0,0)).x;
		return min(d, sdLine(abs(p-vec2(w,h)), vec2(w*0.8,0), vec2(0,0)).x);
	} else if (n == 3) { // L
		float w2 = w*1.5;
		float d = sdLine(p, vec2(-w2,h), vec2(-w2,-h)).x;
		return min(d, sdLine(p, vec2(-w2,h), vec2(w2,h)).x);
	} else if (n == 4) { // C
		vec2 b = vec2(w*1.5, h);
		vec4 r = 1.6*min(w, h)*vec4(1.0, 1.0, 1.0, 1.0);
		float d = sdRoundedBox(p, b, r);
		return length(vec2(d, mix(clamp((p.x-abs(2.0*p.y)+h-w)/2.0, 0.0, 1.0), 0.0, step(p.x, 0.0))));
	} else if (n == 5) { // D
		vec2 b = vec2(w*1.5, h);
		vec4 r = 1.5*min(w, h)*vec4(1.0, 1.0, 0.0, 0.0);
		return abs(sdRoundedBox(p, b, r));
	} else if (n == 6) { // M
		float w2 = w*1.5;
		float d = sdLine(p, vec2(-w2,h), vec2(-w2,-h)).x;
		d = min(d, sdLine(p, vec2(w2,h), vec2(w2,-h)).x);
		d = min(d, sdLine(p, vec2(w2,-h), vec2(0.0, 0.0)).x);
		d = min(d, sdLine(p, vec2(-w2,-h), vec2(0.0, 0.0)).x);
		return d;
	} else {
		return 1.0;
	}
}

float roman2(vec2 p, float w, float h, int n, float bevel, float r, float s, float a)
{
	p -= 0.5;
	h *= 0.5;
	w *= 0.25;
	const int val[] = { 1000, 900, 500, 400, 100, 90, 50, 40, 10,  9,  5,  4,  1};
	const int c1[]  = {	6,   4,   5,   4,   4,  2,  3,  2,  2,  0,  1,  0,  0};
	const int c2[]  = {   -1,   6,  -1,   5,  -1,  4, -1,  3, -1,  2, -1,  1, -1};
	float res = 1.0;
	int n_clamped = clamp(n, 0, 3999);
	n = n_clamped;
	float total_width = 0.0;
	for (int i = 0; i < 13; ++i) {
		while (n - val[i] >= 0) {
			total_width += s;
			if (c2[i] != -1) {
				total_width += s;
			}
			n -= val[i]; 
		}
	}
	n = n_clamped;
	p.x += total_width*a;
	p.x -= 0.5*s;
	for (int i = 0; i < 13; ++i) {
		while (n - val[i] >= 0) {
			res = min(res, roman2_num(p,w,h,s,c1[i]));
			p -= vec2(s,0);
			if (c2[i] != -1) {
				res = min(res, roman2_num(p,w,h,s,c2[i]));
				p -= vec2(s,0);
			}
			n -= val[i]; 
