vec2 rotate(vec2 uv, float rotate) {
 	vec2 rv;
	rv.x = cos(rotate)*uv.x + sin(rotate)*uv.y;
	rv.y = -sin(rotate)*uv.x + cos(rotate)*uv.y;
	return rv;	
}

float ThickLine(vec2 uv, vec2 posA, vec2 posB, float radiusInv)
{
	return clamp(1.1-20.0*sdLine(uv, posA, posB).x, 0.0, 1.0);
}

// makes a rune in the 0..1 uv space. Seed is which rune to draw.
// passes back gray in x and derivates for lighting in yz
float Rune(vec2 uv, float s) {
	float finalLine = 0.0;
	vec2 seed = floor(uv)-rand2(vec2(s));
	uv = fract(uv);
	for (int i = 0; i < 4; i++)	// number of strokes
	{
		vec2 posA = rand2(floor(seed+0.5));
		vec2 posB = rand2(floor(seed+1.5));
		seed += 2.0;
		// expand the range and mod it to get a nicely distributed random number - hopefully. :)
		posA = fract(posA * 128.0);
		posB = fract(posB * 128.0);
		// each rune touches the edge of its box on all 4 sides
		if (i == 0) posA.y = 0.0;
		if (i == 1) posA.x = 0.999;
		if (i == 2) posA.x = 0.0;
		if (i == 3) posA.y = 0.999;
		// snap the random line endpoints to a grid 2x3
		vec2 snaps = vec2(2.0, 3.0);
		posA = (floor(posA * snaps) + 0.5) / snaps;	// + 0.5 to center it in a grid cell
		posB = (floor(posB * snaps) + 0.5) / snaps;
		//if (distance(posA, posB) < 0.0001) continue;	// eliminate dots.
		// Dots (degenerate lines) are not cross-GPU safe without adding 0.001 - divide by 0 error.
		finalLine = max(finalLine, ThickLine(uv, posA, posB + 0.001, 20.0));
	}
	return finalLine;
}

vec2 scale(vec2 uv, vec2 center, vec2 scale) {
	uv -= center;
	uv /= scale;
	uv += center;
	return uv;
}

float old_scratch(vec2 uv, vec2 size, float waviness, float angle, float randomness, vec2 seed) {
	float subdivide = floor(1.0/size.x);
	float cut = size.x*subdivide;
	uv *= subdivide;
	vec2 r1 = rand2(floor(uv)+seed);
	vec2 r2 = rand2(r1);
	uv = fract(uv);
	vec2 border = 10.0*min(fract(uv), 1.0-fract(uv));
	uv = 2.0*uv-vec2(1.0);
	float a = 6.28318530718*(angle+(r1.x-0.5)*randomness);
	float c = cos(a);
	float s = sin(a);
	uv = vec2(c*uv.x+s*uv.y, s*uv.x-c*uv.y);
	uv.y += 2.0*r1.y-1.0;
	uv.y += 0.5*waviness*cos(2.0*uv.x+6.28318530718*r2.y);
	uv.x /= cut;
	uv.y /= subdivide*size.y;
	return min(border.x, border.y)*(1.0-uv.x*uv.x)*max(0.0, 1.0-1000.0*uv.y*uv.y);
}

float old_scratches(vec2 uv, int layers, vec2 size, float waviness, float angle, float randomness, vec2 seed) {
	float v = 0.0;
	for (int i = 0; i < layers; ++i) {
		seed = rand2(seed);
		v = max(v, old_scratch(fract(uv+seed), size, waviness, angle/360.0, randomness, seed));
	}
	return v;
}

float scratch(vec2 uv, vec2 size, float waviness, float angle, float randomness, vec2 seed) {
	float subdivide = floor(1.0/size.x);
	float cut = size.x*subdivide;
	uv *= subdivide;
	vec2 r1 = rand2(floor(uv)+seed);
	vec2 r2 = rand2(r1);
	uv = fract(uv);
	vec2 border = min(fract(uv), 1.0-fract(uv));
	uv = 2.0*uv-vec2(1.0);
	float a = 6.28318530718*(angle+(r1.x-0.5)*randomness);
	float c = cos(a);
	float s = sin(a);
	uv = vec2(c*uv.x+s*uv.y, s*uv.x-c*uv.y);
	uv.y += 2.0*r1.y-1.0;
	uv.y += 0.5*waviness*cos(2.0*uv.x+6.28318530718*r2.y);
	uv.x /= cut;
	uv.y /= subdivide*size.y;
	return min(border.x, border.y)*(1.0-uv.x*uv.x)*max(0.0, 1.0-1000.0*uv.y*uv.y);
}

float scratches(vec2 uv, int layers, vec2 size, float waviness, float angle, float randomness, vec2 seed) {
	float v = 0.0;
	for (int i = 0; i < layers; ++i) {
		seed = rand2(seed);
		v = max(v, scratch(fract(uv+seed), size, waviness, angle/360.0, randomness, seed));
	}
	return v * 2.0;
}

shader_model.instance:
vec3 $(name)_jump_flood(vec2 uv, float size) {
	ivec2 int_uv = ivec2(uv * size);
	float best_distance = 9999.9;
	vec2 best_coord = vec2(0.0);
	float iter = $in(uv).b;
	iter += 0.01;
	float step_width = size / 4.0 / (iter * 100.0);

	for (int x = -1; x <= 1; x++) {
		for (int y = -1; y <= 1; y++) {
			ivec2 offsetUV = int_uv + ivec2(x, y) * int(step_width);
			vec2 float_uv = vec2(offsetUV) / size;
			vec2 offset_pos = $in(float_uv).rg;

			if (offset_pos.x != 0.0 && offset_pos.y != 0.0) {
				vec2 diff = offset_pos - uv;
				//float dist = dot(diff, diff);
				$distance
				if (dist < best_distance) {
					best_distance = dist;
					best_coord = offset_pos;
				}
			}
		}
	}

	return vec3(best_coord, iter);
}

float $(name)_distance(vec2 uv, bool tiled) {
	if (tiled) {
		uv = fract(uv);
	}
	vec2 custom_uv = $in(uv).xy;
	vec2 diff = custom_uv != vec2(0.0) ? custom_uv - uv : vec2(1.0);
	$distance
	if (!tiled) {
		uv = clamp(uv, 0.0, 1.0);
	}
	return $mask(uv) < 0.5 ? distance : -distance;
}

shader_model.global:
float sdRipples(float d, float w, int r) {
	for (int i = 0; i < r; ++i) {
		d = abs(d)-w;
	}
	return d;
}

float sdArc(vec2 p, float a1, float a2, float ra, float rb) {
	float amid = 0.5*(a1+a2)+1.6+3.14*step(a1, a2);
	float alength = 0.5*(a1-a2)-1.6+3.14*step(a1, a2);
	vec2 sca = vec2(cos(amid), sin(amid));
	vec2 scb = vec2(cos(alength), sin(alength));
	p *= mat2(vec2(sca.x,sca.y),vec2(-sca.y,sca.x));
	p.x = abs(p.x);
	float k = (scb.y*p.x>scb.x*p.y) ? dot(p.xy,scb) : length(p.xy);
	return sqrt( max(0.0, dot(p,p) + ra*ra - 2.0*ra*k) ) - rb;
}

// The MIT License, Copyright © 2021 Inigo Quilez
// https://www.shadertoy.com/view/slj3Dd

float sdArrow( in vec2 p, vec2 a, vec2 b, float w1, float w2, float k)
{
	// constant setup
	vec2  ba = b - a;
	float l2 = dot(ba,ba);
	float l = sqrt(l2);


	// pixel setup
	p = p-a;
	p = mat2(vec2(ba.x,-ba.y),vec2(ba.y,ba.x))*p/l;
	p.y = abs(p.y);
	vec2 pz = p-vec2(l-w2*k,w2);


	// === distance (four segments) === 

	vec2 q = p;
	q.x -= clamp( q.x, 0.0, l-w2*k );
	q.y -= w1;
	float di = dot(q,q);

	//----
	q = pz;
	q.y -= clamp( q.y, w1-w2, 0.0 );
	di = min( di, dot(q,q) );
	//----
	if( p.x<w1 ) // conditional is optional
	{
	q = p;
	q.y -= clamp( q.y, 0.0, w1 );
	di = min( di, dot(q,q) );
	}
	//----
	if( pz.x>0.0 ) // conditional is optional
	{
	q = pz;
	q -= vec2(k,-1.0)*clamp( (q.x*k-q.y)/(k*k+1.0), 0.0, w2 );
	di = min( di, dot(q,q) );
	}

	// === sign === 

	float si = 1.0;
	float z = l - p.x;
	if( min(p.x,z)>0.0 ) //if( p.x>0.0 && z>0.0 )
	{
	  float h = (pz.x<0.0) ? w1 : z/k;
	  if( p.y<h ) si = -1.0;
	}
	return si*sqrt(di);
}

vec2 sdBend(vec2 uv, float r) {
	const float k = 10.0;
	float c = cos(r*uv.x);
	float s = sin(r*uv.x);
	mat2  m = mat2(vec2(c,-s),vec2(s,c));
	return m*uv;
}

float sd_box(vec2 uv, vec2 size) {
	vec2 d = abs(uv)-size;
	return length(max(d, vec2(0)))+min(max(d.x, d.y), 0.0);
}

vec2 circle_repeat_transform_2d(vec2 p, float count) {
	float r = 6.28318530718/count;
	float pa = atan(p.x, p.y);
	float a = mod(pa+0.5*r, r)-0.5*r;
	vec2 rv;
	float c = cos(a-pa);
	float s = sin(a-pa);
	rv.x = p.x*c+p.y*s;
	rv.y = -p.x*s+p.y*c;
	return rv;
}

float sdCross( in vec2 p, in vec2 b, float r ) 
{
    p = abs(p); p = (p.y>p.x) ? p.yx : p.xy;
    vec2  q = p - b;
    float k = max(q.y,q.x);
    vec2  w = (k>0.0) ? q : vec2(b.y-p.x,-k);
    return sign(k)*length(max(w,0.0)) + r;
}

float sdCutDisk( in vec2 p, in float r, in float h )
{
    float w = sqrt(r*r-h*h); // constant for any given shape
    p.x = abs(p.x);
    float s = max( (h-r)*p.x*p.x+w*w*(h+r-2.0*p.y), h*p.x-w*p.y );
    return (s<0.0) ? length(p)-r : ((p.x<w) ? h - p.y : length(p-vec2(w,h)));
}

float sdEgg( in vec2 p, in float ra, in float rb )
{
	p = vec2(p.x,-p.y);
	float k = sqrt(3.0);
	p.x = abs(p.x);
	float r = ra - rb;
	return ((p.y<0.0)	   ? length(vec2(p.x,  p.y	)) - r :
			((k*(p.x+r)<p.y) ? length(vec2(p.x,  p.y-k*r)) :
							  length(vec2(p.x+r,p.y	)) - 2.0*r)) - rb;
}

// The MIT License, Copyright © 2015 Inigo Quilez
float sd_ellipse( vec2 p, vec2 ab )
{
	// symmetry
	p = abs( p );

	// find root with Newton solver
	vec2 q = ab*(p-ab);
	float w = (q.x<q.y)? 1.570796327 : 0.0;
	for( int i=0; i<5; i++ )
	{
		vec2 cs = vec2(cos(w),sin(w));
		vec2 u = ab*vec2( cs.x,cs.y);
		vec2 v = ab*vec2(-cs.y,cs.x);
		w = w + dot(p-u,v)/(dot(p-u,u)+dot(v,v));
	}

	// compute final point and distance
	float d = length(p-ab*vec2(cos(w),sin(w)));

	// return signed distance
	return (dot(p/ab,p/ab)>1.0) ? d : -d;
}

float sdEquilateralTriangle( in vec2 p )
{
    float k = sqrt(3.0);
    p.x = abs(p.x) - 1.0;
    p.y = -p.y + 1.0/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0, 0.0 );
    return -length(p)*sign(p.y);
}

