float sdCone(vec3 p, vec2 q) {
  vec2 w = vec2( length(p.xz), p.y );
  vec2 a = w - q*clamp( dot(w,q)/dot(q,q), 0.0, 1.0 );
  vec2 b = w - q*vec2( clamp( w.x/q.x, 0.0, 1.0 ), 1.0 );
  float k = sign( q.y );
  float d = min(dot( a, a ),dot(b, b));
  float s = max( k*(w.x*q.y-w.y*q.x),k*(w.y-q.y)  );
  return sqrt(d)*sign(s);
}

// The MIT License
// Copyright © 2021 Inigo Quilez
// source: https://www.shadertoy.com/view/stKSzc
float sdCutSphere( vec3 p, float r, float h )
{
	// sampling independent computations (only depend on shape)
	float w = sqrt(r*r-h*h);

	// sampling dependant computations
	vec2 q = vec2( length(p.xz), p.y );
	float s = max( (h-r)*q.x*q.x+w*w*(h+r-2.0*q.y), h*q.x-w*q.y );

	float res = 0.0;

	if (s<0.0)
		res = length(q)-r;
	else {
		if (q.x<w)
			res = h - q.y;
		else
			res = length(q-vec2(w,h));
	}
	return res;
}

float sdCylinder(vec3 p, float h, float r) {
	vec2 d = abs(vec2(length(p.xz), p.y)) - vec2(r, h);
	return min(max(d.x, d.y),0.0) + length(max(d, 0.0));
}

// The MIT License, Copyright © 2019 Inigo Quilez
// source: https://www.shadertoy.com/view/tdS3DG
float sdEllipsoid(vec3 p, vec3 r)  {
	float k0 = length(p/r);
	float k1 = length(p/(r*r));
	return k0*(k0-1.0)/k1;
}

// https://iquilezles.org/www/articles/fbmsdf/fbmsdf.htm
float fbm_sph( ivec3 i, vec3 f, ivec3 c, float seed )
{
	// Line below randomizes the positions of each sphere, this can cause a bit of artifacting,
