	//f += rand3( vec2(i.xy + c.xy) - vec2( float(i.z + c.z) ) ) - vec3(0.5);
	// random radius at grid vertex i+c
	float rad = 0.5*rand31(vec3(i+c) + vec3(seed));
	// distance to sphere at grid vertex i+c
	return length(f-vec3(c)) - rad; 
}

float sdBase( vec3 p, float seed )
{
   ivec3 i = ivec3(floor(p));
	vec3 f =	   fract(p);
   // distance to the 8 corners spheres
   return min(min(min(fbm_sph(i,f,ivec3(0,0,0), seed),
					  fbm_sph(i,f,ivec3(0,0,1), seed)),
				  min(fbm_sph(i,f,ivec3(0,1,0), seed),
					  fbm_sph(i,f,ivec3(0,1,1), seed))),
			  min(min(fbm_sph(i,f,ivec3(1,0,0), seed),
					  fbm_sph(i,f,ivec3(1,0,1), seed)),
				  min(fbm_sph(i,f,ivec3(1,1,0), seed),
					  fbm_sph(i,f,ivec3(1,1,1), seed))));
}

float sdFbm( vec3 p, float d, int iterations, float smoothness, float seed, float scaling, int mode)
{
	float s = 1.0;
	for( int i=0; i<iterations; i++ )
	{
		// evaluate new octave
		float n = s*sdBase(p, seed);

		if(mode == 0) {
			// add
			n = smax(n,d - scaling * s,smoothness * s);
			d = smin(n,d			 ,smoothness * s);
		} else {
			// subtract
			d = smax(d - scaling * s, -n, smoothness * s );
		}

		// prepare next octave
		p = mat3(vec3(0.02, 1.60, 1.20),
				vec3(-1.60, 0.72,-0.96),
				vec3(-1.20,-0.96, 1.28))*p;
		s = 0.5*s;
	}
	return d;
}

// https://iquilezles.org/www/articles/fbmsdf/fbmsdf.htm
float fbm_sph( ivec3 i, vec3 f, ivec3 c, float seed )
{
	// Line below randomizes the positions of each sphere, this can cause a bit of artifacting,
