	//f += rand3( vec2(i.xy + c.xy) - vec2( float(i.z + c.z) ) ) - vec3(0.5);
	// random radius at grid vertex i+c
	float rad = 0.5*rand31(vec3(i+c) + vec3(seed));
	// distance to sphere at grid vertex i+c
	return length(f-vec3(c)) - rad; 
}

float sdBase( vec3 p, float seed )
{
   ivec3 i = ivec3(floor(p));
	vec3 f =	   fract(p);
   // distance to the 8 corners spheres
   return min(min(min(fbm_sph(i,f,ivec3(0,0,0), seed),
					  fbm_sph(i,f,ivec3(0,0,1), seed)),
				  min(fbm_sph(i,f,ivec3(0,1,0), seed),
