float sdFbm( vec3 p, float d, int iterations, float smoothness, float seed, float scaling, int _mode)
{
	float s = 1.0;
	for( int i=0; i<iterations; i++ )
	{
		// evaluate new octave
		float n = s*sdBase(p, seed);

		if(_mode == 0) {
			// add
			n = smax(n,d - scaling * s,smoothness * s);
			d = smin(n,d			 ,smoothness * s);
		} else {
