			d = smax(d - scaling * s, -n, smoothness * s );
		}

		// prepare next octave
		p = mat3(vec3(0.02, 1.60, 1.20),
				vec3(-1.60, 0.72,-0.96),
				vec3(-1.20,-0.96, 1.28))*p;
		s = 0.5*s;
	}
