float sdSolidAngle(vec3 p, float a, float ra)
{
	vec2 c = vec2(sin(a),cos(a));
	vec2 q = vec2( length(p.xz), p.y );
	float l = length(q) - ra;
	float m = length(q - c*clamp(dot(q,c),0.0,ra) );
	return max(l,m*sign(c.y*q.x-c.x*q.y));
}

float sdTorus(vec3 p, vec2 t) {
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

float sdHeart( in vec2 p )
{
    p.x = abs(p.x);
	p.y = 0.5 - p.y;

    if( p.y+p.x>1.0 )
        return sqrt(dot2(p-vec2(0.25,0.75))) - sqrt(2.0)/4.0;
    return sqrt(min(dot2(p-vec2(0.00,1.00)),
                    dot2(p-0.5*max(p.x+p.y,0.0)))) * sign(p.x-p.y);
}

float sdHexagram( in vec2 p, in float r )
{
    const vec4 k = vec4(-0.5,0.8660254038,0.5773502692,1.7320508076);
    p = abs(p);
    p -= 2.0*min(dot(k.xy,p),0.0)*k.xy;
    p -= 2.0*min(dot(k.yx,p),0.0)*k.yx;
    p -= vec2(clamp(p.x,r*k.z,r*k.w),r);
    return length(p)*sign(p.y);
}

float sd_isosceles_triangle(vec2 uv, vec2 size)
{
	uv.x = abs(uv.x);
	uv.y += size.y; size.y *= 2.0;
	vec2 a = uv - size*clamp(dot(uv,size)/dot(size,size), 0.0, 1.0);
	vec2 b = uv - size*vec2(clamp(uv.x/size.x, 0.0, 1.0), 1.0);
	float s = -sign(size.y);
	vec2 d = min(vec2(dot(a,a), s*(uv.x*size.y-uv.y*size.x)),
				 vec2(dot(b,b), s*(uv.y-size.y)));
	return -sqrt(d.x)*sign(d.y);
}

float sdKite(vec2 p, float w, float hb, float ht) {
	vec2 v[] = { vec2(-w, 0.0), vec2(0.0, ht), vec2(w, 0.0), vec2(0.0, hb) };
	int l = 4;
	float d = dot(p-v[0],p-v[0]);
	float s = 1.0;
	int j = l-1;
	for(int i=0; i<l; i++)
	{
		vec2 e = v[j] - v[i];
		vec2 w = p - v[i];
		vec2 b = w - e*clamp( dot(w,e)/dot(e,e), 0.0, 1.0 );
		d = min( d, dot(b,b) );
		bvec3 c = bvec3(p.y>=v[i].y,p.y<v[j].y,e.x*w.y>e.y*w.x);
		if( all(c) || all(not(c)) ) s*=-1.0;
		j=i;
	}
	return s*sqrt(d);
}

vec2 sdLine(vec2 p, vec2 a, vec2 b) {
	vec2 pa = p-a, ba = b-a;
	float h = clamp(dot(pa,ba)/dot(ba,ba), 0.0, 1.0);
	return vec2(length(pa-ba*h), h);
}

float sdMoon(vec2 p, float d, float ra, float rb )
{
    p.y = abs(p.y);
    float a = (ra*ra - rb*rb + d*d)/(2.0*d);
    float b = sqrt(max(ra*ra-a*a,0.0));
    if( d*(p.x*b-p.y*a) > d*d*max(b-p.y,0.0) )
          return length(p-vec2(a,b));
    return max( (length(p          )-ra),
               -(length(p-vec2(d,0))-rb));
}

float sdNgon(vec2 p, float r, float n) {
	p = circle_repeat_transform_2d(p, n);
	vec2 d = abs(p)-vec2(r*tan(3.14159265359/n), r);
	return p.y < r ? p.y-r : length(max(d,vec2(0)))+min(max(d.x,d.y),0.0);
}

float sdParallelogram( in vec2 p, float wi, float he, float sk )
{
    vec2 e = vec2(-sk,he);
    p = (p.y<0.0)?-p:p;
    vec2  w = p - e; w.x -= clamp(w.x,-wi,wi);
    vec2  d = vec2(dot(w,w), -w.y);
    float s = p.x*e.y - p.y*e.x;
    p = (s<0.0)?-p:p;
    vec2  v = p - vec2(wi,0); v -= e*clamp(dot(v,e)/dot(e,e),-1.0,1.0);
    d = min( d, vec2(dot(v,v), wi*he-abs(s)));
    return sqrt(d.x)*sign(-d.y);
}

float sdPie( in vec2 p, in vec2 c, in float r )
{
    p.x = abs(p.x);
    float l = length(p) - r;
    float m = length(p-c*clamp(dot(p,c),0.0,r)); // c=sin/cos of aperture
    return max(l,m*sign(c.y*p.x-c.x*p.y));
}

