float sdPolygon_$(name)(vec2 p) {
	vec2 v[] = $polygon;
	int l = v.length();
	float d = dot(p-v[0],p-v[0]);
	float s = 1.0;
	int j = l-1;
	for(int i=0; i<l; i++)
	{
		vec2 e = v[j] - v[i];
		vec2 w =	p - v[i];
		vec2 b = w - e*clamp( dot(w,e)/dot(e,e), 0.0, 1.0 );
		d = min( d, dot(b,b) );
		bvec3 c = bvec3(p.y>=v[i].y,p.y<v[j].y,e.x*w.y>e.y*w.x);
		if( all(c) || all(not(c)) ) s*=-1.0;
		j=i;
	}
	return s*sqrt(d);
}

