shader_model.global:
vec2 repeat_2d(vec2 p, vec2 r, float seed, float randomness) {
	p -= vec2(0.5);
	float a = (rand(floor(mod((p.xy+0.5*r.xy)/r.xy, 1.0/r.xy))+vec2(seed))-0.5)*6.28*randomness;
	p = mod(p+0.5*r,r)-0.5*r;
	vec2 rv;
	float c = cos(a);
	float s = sin(a);
	rv.x = p.x*c+p.y*s;
	rv.y = -p.x*s+p.y*c;
	return rv+vec2(0.5);
}

float sdr_ndot(vec2 a, vec2 b) { return a.x*b.x - a.y*b.y; }
float sdRhombus(in vec2 p, in vec2 b) {
	vec2 q = abs(p);
	float h = clamp((-2.0*sdr_ndot(q,b)+sdr_ndot(b,b))/dot(b,b),-1.0,1.0);
	float d = length( q - 0.5*b*vec2(1.0-h,1.0+h) );
	return d * sign( q.x*b.y + q.y*b.x - b.x*b.y );
}

vec2 sdf2d_rotate(vec2 uv, float a) {
	vec2 rv;
	float c = cos(a);
	float s = sin(a);
	uv -= vec2(0.5);
	rv.x = uv.x*c+uv.y*s;
	rv.y = -uv.x*s+uv.y*c;
	return rv+vec2(0.5);
}

float sdRoundedBox( in vec2 p, in vec2 b, in vec4 r )
{
	r.xy = (p.x>0.0)?r.xy : r.zw;
	r.x  = (p.y>0.0)?r.x  : r.y;
	vec2 q = abs(p)-b+r.x;
	return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r.x;
}

float sdRoundedCross( in vec2 p, in float h )
{
	float k = 0.5*(h+1.0/h); // k should be const at modeling time
	p = abs(p);
	return ( p.x<1.0 && p.y<p.x*(k-h)+h ) ? 
			 k-sqrt(dot2(p-vec2(1,k)))  :
		   sqrt(min(dot2(p-vec2(0,h)),
					dot2(p-vec2(1,0))));
}

float sdRoundedX( in vec2 p, in float w, in float r )
{
    p = abs(p);
    return length(p-min(p.x+p.y,w)*0.5) - r;
}

