float m(vec4 a, vec4 b)
{
	return max(max(max(a.x,a.y),max(a.z,a.w)),max(max(b.x,b.y),max(b.z,b.w)));
}

vec4 fs(vec2 p,float s, float st, float sl, bool is_top)
{
	sl = (1.0 - sl)/2.0; st /= 2.0;
	sl = clamp(sl, 0.0,1.0);

	p = 2.5*(1.0/s)*(p - 0.5)-vec2(0.0, is_top ? -0.5 : 0.5);
	vec2 p1 = p; vec2 p2 = p;

	p = abs(p)-0.5;
	vec4 d = vec4(min(st - abs(max(p.x, p.y) * -1.0),
		min(-dot(p, normalize(vec2(1.0, 1.0))),
		abs(dot(p, normalize(vec2(1.0, -1.0))))) - sl));

	p1.x = abs(p1.x);
	p2.y = abs(p2.y);

	float q1 = -dot(p1,vec2(1.0,1.0));
	float q2 = -dot(p2,vec2(-1.0,1.0));
	float q3 = dot(p1,vec2(-1.0,1.0));
	float q4 = -dot(p2,vec2(1.0,1.0));

	return min(d,vec4(q1,q2,q3,q4));
}

float ssd(vec2 p, float s, float st, float sl, float bevel, int num)
{
	vec4 a = fs(p,s,st,sl,true);
	vec4 b = fs(p,s,st,sl,false);

	float d;

	vec4 x = vec4(0.0);

	if (num == 0) d = m(vec4(a.xyw,b.y),vec4(b.zw,x.xx));
	if (num == 1) d = m(vec4(a.y,b.y,x.xx),x);
	if (num == 2) d = m(vec4(a.xyz,b.w),vec4(b.z,x.xxx));
	if (num == 3) d = m(vec4(a.xyz,b.y),vec4(b.z,x.xxx));
	if (num == 4) d = m(vec4(a.yzw,b.y),x);
	if (num == 5) d = m(vec4(a.xwz,b.y),vec4(b.z,x.xxx));
	if (num == 6) d = m(vec4(a.xwz,b.y),vec4(b.zw,x.xx));
	if (num == 7) d = m(vec4(a.xy,b.y,x.x),x);
	if (num == 8) d = m(a,b);
	if (num == 9) d = m(a,vec4(b.yz,x.xx));

	return clamp(d/max(bevel, 0.00001), 0.0, 1.0);
}

