	uv = 2.0*uv-1.0;
	edge = max(edge, 1.0e-8);
	float angle = atan(uv.x, uv.y)+3.14159265359;
	float slice = 6.28318530718/sides;
	return clamp((1.0-(cos(floor(0.5+angle/slice)*slice-angle)*length(uv))/size)/edge, 0.0, 1.0);
}

float shape_star(vec2 uv, float sides, float size, float edge) {
	uv = 2.0*uv-1.0;
	edge = max(edge, 1.0e-8);
	float angle = atan(uv.x, uv.y);
	float slice = 6.28318530718/sides;
	return clamp((1.0-(cos(floor(angle*sides/6.28318530718-0.5+2.0*step(fract(angle*sides/6.28318530718), 0.5))*slice-angle)*length(uv))/size)/edge, 0.0, 1.0);
}

float shape_curved_star(vec2 uv, float sides, float size, float edge) {
	uv = 2.0*uv-1.0;
	edge = max(edge, 1.0e-8);
	float angle = 2.0*(atan(uv.x, uv.y)+3.14159265359);
	float slice = 6.28318530718/sides;
	return clamp((1.0-cos(floor(0.5+0.5*angle/slice)*2.0*slice-angle)*length(uv)/size)/edge, 0.0, 1.0);
}

float shape_rays(vec2 uv, float sides, float size, float edge) {
	uv = 2.0*uv-1.0;
	edge = 0.5*max(edge, 1.0e-8)*size;
	float slice = 6.28318530718/sides;
	float angle = mod(atan(uv.x, uv.y)+3.14159265359, slice)/slice;
	return clamp(min((size-angle)/edge, angle/edge), 0.0, 1.0);
}

// Adapted from https://www.shadertoy.com/view/dlKyWw by @ENDESGA

vec3 hash(vec3 p)
{
	p = vec3(dot(p, vec3(127.1, 311.7, 74.7)), dot(p, vec3(269.5,183.3,246.1)), dot(p, vec3(113.5, 271.9, 124.6)));
	p = fract(sin(p) * 43758.5453123);
	return p;
}

float shard_noise(vec3 p, vec3 size, float sharpness, float seed) {
	vec3 ip = floor(p);
	vec3 fp = fract(p);

	float v = 0.0, t = 0.0;

	for (int z = -1; z <= 1; z++) {
		for (int y = -2; y <= 2; y++) {
			for (int x = -2; x <= 2; x++) {

				vec3 o = vec3(float(x), float(y), float(z));
				vec3 io = mod(ip + o, size);
				vec3 h = hash(io + seed);
				vec3 r = fp - (o + h);

				float w = exp2(-6.283185*dot(r, r));
				// tanh deconstruction and optimization by @Xor
				float s = sharpness * dot(r, hash(io + vec3(11, 31, 47)) - 0.5);
				v += w * s*inversesqrt(1.0+s*s);
				t += w;
			}
		}
	}
	return ((v / t) * 0.5) + 0.5;
}

float fbm_shard(vec3 coord, vec3 size, int folds, int octaves, float persistence, float sharpness, float seed) {
	float normalize_factor = 0.0;
	float value = 0.0;
	float scale = 1.0;
	for (int i = 0; i < octaves; i++) {
		float noise = shard_noise(coord*size, size, sharpness, seed);
		for (int f = 0; f < folds; ++f) {
			noise = abs(2.0*noise-1.0);
		}
		value += noise * scale;
		normalize_factor += scale;
		size *= 2.0;
		scale *= persistence;
	}
	return value / normalize_factor;
}

shader_model.instance:
vec3 $(name)_fct(vec2 uv) {
	vec2 e = vec2(1.0/$size, 0.0);
	vec3 rv = 5.0*$in(uv);
	rv -= $in(uv+e.xy);
	rv -= $in(uv-e.xy);
	rv -= $in(uv+e.yx);
	rv -= $in(uv-e.yx);
	return rv;
}

