shader_model.global:
float skewed_brick_rand(vec2 x) {
	// To avoid weird precission errors I was having
	x *= 4096.0;
	x = round(x);
	return rand(x);
}

vec2 perpendicular(vec2 vector) {
	vector = vector.yx;
	vector.y = -vector.y;
	return vector;
}

// https://wiki.secondlife.com/wiki/Geometric#Line_and_Line.2C_intersection_point
// Copyright 2001, softSurfer (www.softsurfer.com); 2008, LSL-port by Nexii Malthus
// (CC BY-SA 3.0 License)
vec2 get_line_intersection(vec4 line1, vec4 line2) {
	vec2 A = line1.xy;
	vec2 B = line1.zw;
	vec2 C = line2.xy;
	vec2 D = line2.zw;

	vec2 b = B - A;
	vec2 d = D - C;
	float dotperp = b.x * d.y - b.y * d.x;
	// if I had to worry about parallel lines, but I shouldn't have to here
	// if (dotperp == 0) return <-1,-1,-1>;
	vec2 c = C - A;
	float t = (c.x * d.y - c.y * d.x) / dotperp;
	return vec2(A.x + t * b.x, A.y + t * b.y);
}

float skewed_bricks(vec2 uv, vec2 scale, float offset, float randomness, float mortar, float bevel, float round_radius, float corner, float seed, inout vec3 brick_uv, inout vec3 corner_uv, inout vec4 brick_fill, inout vec4 corner_fill) {
	// rb2
	//scale.x *= 1.0 + step(0.5, fract(uv.y * scale.y * 0.5));

	vec2 scaled_uv = uv * scale;

	float x_offset = offset * step(0.5, fract(uv.y * scale.y * 0.5));

	vec2 cell_id = floor(scaled_uv);
	vec2 cell_uv = fract(scaled_uv);

	cell_id -= vec2(x_offset, 0.0);

	float min_distance = 1.0;
	vec2 c_point;
	vec2 left_top;
	vec2 right_top;
	vec2 right_bottom;
	vec2 left_bottom;

	for (int i = -1; i <= 1; i++) {
		// neighbor in uv space
		vec2 neighbor = vec2(float(i), 0.0);
		vec2 point = cell_id + neighbor + vec2(0.5) + (vec2(0.0, skewed_brick_rand(mod(cell_id + neighbor + seed, scale)) - 0.5) * randomness * scale.y / 4.0);
		point /= scale;
		float dist = distance(point, uv);

		// get left, right neighbor in here as well, to calculate perpendicular and intersect
		vec2 left = cell_id + neighbor + vec2(-1.0, 0.0) + vec2(0.5) + (vec2(0.0, skewed_brick_rand(mod(cell_id + neighbor + vec2(-1.0, 0.0) + seed, scale)) - 0.5) * randomness * scale.y / 4.0);
		left /= scale;
		vec2 right = cell_id + neighbor + vec2(1.0, 0.0) + vec2(0.5) + (vec2(0.0, skewed_brick_rand(mod(cell_id + neighbor + vec2(1.0, 0.0) + seed, scale)) - 0.5) * randomness * scale.y / 4.0);
		right /= scale;

		// Find the midpoint between current and left and a vector perpendicular to the vector between the two points
		vec2 left_midpoint = (left + point) / 2.0;
		vec2 left_perpendicular = perpendicular(point - left);
		vec2 left_2 = left_midpoint + left_perpendicular;
		// Do the same for midpoint to right point
		vec2 right_midpoint = (point + right) / 2.0;
		vec2 right_perpendicular = perpendicular(right - point);
		vec2 right_2 = right_midpoint + right_perpendicular;

		if (dist < min_distance) {
			min_distance = dist;
			c_point = point;
			left_top = get_line_intersection(vec4(left_midpoint, left_2), vec4(cell_id / scale, cell_id / scale + vec2(1.0, 0.0)));
			right_top = get_line_intersection(vec4(right_midpoint, right_2), vec4(cell_id / scale, cell_id / scale + vec2(1.0, 0.0)));
			right_bottom = get_line_intersection(vec4(right_midpoint, right_2), vec4((cell_id + 1.0) / scale, (cell_id + 1.0) / scale + vec2(1.0, 0.0)));
			left_bottom = get_line_intersection(vec4(left_midpoint, left_2), vec4((cell_id + 1.0) / scale, (cell_id + 1.0) / scale + vec2(1.0, 0.0)));
		}
	}

	// The bricks skewed uv.x gradient
	float grad = (uv.x - mix(left_top.x, left_bottom.x, cell_uv.y)) / mix(right_top.x - left_top.x, right_bottom.x - left_bottom.x, cell_uv.y);

	brick_uv = vec3(grad, cell_uv.y, skewed_brick_rand(fract(c_point)));

	corner_uv.xy = scale.yx / corner / 8.0 * (1.0 - (2.0 * abs(brick_uv.xy - 0.5)));
	corner_uv.x = brick_uv.x < 0.5 ? corner_uv.x : 1.0 - corner_uv.x;
	corner_uv.y = brick_uv.y < 0.5 ? corner_uv.y : 1.0 - corner_uv.y;
	corner_uv.z = skewed_brick_rand( floor(brick_uv.xy * 2.0) + fract(c_point) );

	// Calculate bounding box
	brick_fill.x = min(left_top.x, left_bottom.x);
	brick_fill.y = min(left_top.y, right_top.y);
	brick_fill.z = max(right_top.x, right_bottom.x);
	brick_fill.z = brick_fill.z - brick_fill.x;
	brick_fill.w = 1.0 / scale.y;
	brick_fill.xy = fract(brick_fill.xy);
	// Calculate corner bounding box
	float half_corner_size = 1.0 / scale.y * corner * 0.5;
	vec2 top_centers = brick_uv.x < 0.5 ? left_top + (normalize(left_bottom - left_top) + vec2(1.0, 0.0)) * half_corner_size : right_top + (normalize(right_bottom - right_top) - vec2(1.0, 0.0)) * half_corner_size; 
	vec2 bottom_centers = brick_uv.x < 0.5 ? left_bottom + (normalize(left_top - left_bottom) + vec2(1.0, 0.0)) * half_corner_size : right_bottom + (normalize(right_top - right_bottom) - vec2(1.0, 0.0)) * half_corner_size; 
	corner_fill.xy = brick_uv.y < 0.5 ? top_centers : bottom_centers;
	corner_fill.xy -= half_corner_size;
	corner_fill.zw = vec2(half_corner_size * 2.0);
	corner_fill = fract(corner_fill);
	corner_fill *= 4096.0;
	corner_fill = round(corner_fill);
	corner_fill /= 4096.0;
	// Round values to avoid precission errors
	brick_fill *= 4096.0;
	brick_fill = round(brick_fill);
	brick_fill /= 4096.0;

	// Render the brick
	float brick_height = 1.0 / scale.y;
	round_radius /= brick_height;
	mortar /= brick_height;
	bevel /= brick_height;

	float color;
	vec2 d = (min(brick_uv.xy, 1.0 - brick_uv.xy) * -2.0)*scale.yx+vec2(round_radius+mortar);
	color = length(max(d,vec2(0))) + min(max(d.x,d.y),0.0)-round_radius;
	color = clamp(-color/bevel, 0.0, 1.0);

	return color;
}

