vec4 generate_rect(vec2 a, vec2 b, vec2 c, vec2 d) {
	vec2 start = min(min(a, b), min(c, d));
	vec2 end = max(max(a, b), max(c, d));
	return vec4(start, end);
}

float cross2d( in vec2 a, in vec2 b ) { return a.x*b.y - a.y*b.x; }

vec2 invBilinear( in vec2 p, in vec2 a, in vec2 b, in vec2 c, in vec2 d )
{
	vec2 res = vec2(-1.0);

	vec2 e = b-a;
	vec2 f = d-a;
	vec2 g = a-b+c-d;
	vec2 h = p-a;

	float k2 = cross2d( g, f );
	float k1 = cross2d( e, f ) + cross2d( h, g );
	float k0 = cross2d( h, e );
	k2 /= k0; k1 /= k0; k0 = 1.0;

	// if edges are parallel, this is a linear equation
	if( abs(k2)<0.001 )
	{
		res = vec2( (h.x*k1+f.x*k0)/(e.x*k1-g.x*k0), -k0/k1 );
	}
	// otherwise, it's a quadratic
	else
	{
		float w = k1*k1 - 4.0*k0*k2;
		if( w<0.0 ) return vec2(-1.0);
		w = sqrt( w );

		float ik2 = 0.5/k2;
		float v = (-k1 - w)*ik2;
		float u = (h.x - f.x*v)/(e.x + g.x*v);

		if( u<0.0 || u>1.0 || v<0.0 || v>1.0 )
		{
		   v = (-k1 + w)*ik2;
		   u = (h.x - f.x*v)/(e.x + g.x*v);
		}
		res = vec2( u, v );
	}

	return res;
}

bool point_left_of_line(vec4 line, vec2 c) {
	vec2 a = line.xy;
	vec2 b = line.zw;
	return ((b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)) > 0.0;
}

vec2 skewed_uneven_cut(vec2 x, vec2 size, float randomness) {
	const float grid_size = 4096.0;
	return 0.5 + (rand2(round(mod(x, size)*grid_size)/grid_size) - 0.5) * randomness;
}

float skewed_uneven_bricks(vec2 uv, vec2 size, float randomness, float mortar, float bevel, float round_radius, float corner, float seed, out vec3 brick_uv, out vec3 corner_uv, out vec4 brick_fill, out vec4 corner_fill) {
	const float grid_size = 4096.0;

	// Algorithm messes up at randomness 0.0
	randomness = abs(randomness) < 0.001 ? 0.001 : randomness;

	uv = fract(uv);
	vec2 scaled_uv = uv * size;

	vec2 cell_id = floor(scaled_uv);
	vec2 cell_uv = fract(scaled_uv);

	// Instead of creaing one value for each tile, we create two that we can use for a line
	// to cut with.
	// Two random values for each cell
	vec2 current = skewed_uneven_cut(cell_id + seed, size, randomness);
	vec2 top = skewed_uneven_cut( cell_id + vec2(0.0, -1.0) + seed, size, randomness);
	vec2 top_right = skewed_uneven_cut( cell_id + vec2(1.0, -1.0) + seed, size, randomness);
	vec2 right = skewed_uneven_cut( cell_id + vec2(1.0, 0.0) + seed, size, randomness);
	vec2 bottom_right = skewed_uneven_cut( cell_id + vec2(1.0, 1.0) + seed, size, randomness);
	vec2 bottom = skewed_uneven_cut( cell_id + vec2(0.0, 1.0) + seed, size, randomness);
	vec2 bottom_left = skewed_uneven_cut( cell_id + vec2(-1.0, 1.0) + seed, size, randomness);
	vec2 left = skewed_uneven_cut( cell_id + vec2(-1.0, 0.0) + seed, size, randomness);
	vec2 top_left = skewed_uneven_cut( cell_id + vec2(-1.0, -1.0) + seed, size, randomness);

	vec3 color = vec3(0.0);

	//vec2 point = vec2(-0.5);
	vec2 a, b, c, d;
	vec4 rect;

		// Horizontal
	if (mod(cell_id.x + cell_id.y, 2.0) > 0.5) {		
		// The nine lines for horizontal cuts
		vec4 current_line = (cell_id.xyxy + vec4(vec2(-1.0, current.x), vec2(2.0, current.y))) / size.xyxy;
		vec4 top_line = (cell_id.xyxy + vec4(vec2(top.x, -2.0), vec2(top.y, 1.0))) / size.xyxy;
		vec4 top_right_line = (cell_id.xyxy + vec4(vec2(0.0, -1.0 + top_right.x), vec2(3.0, -1.0 + top_right.y))) / size.xyxy;
		vec4 right_line = (cell_id.xyxy + vec4(vec2(1.0 + right.x, -1.0), vec2(1.0 + right.y, 2.0))) / size.xyxy;
		vec4 bottom_right_line = (cell_id.xyxy + vec4(vec2(0.0, 1.0 + bottom_right.x), vec2(3.0, 1.0 + bottom_right.y))) / size.xyxy;
		vec4 bottom_line = (cell_id.xyxy + vec4(vec2(bottom.x, 0.0), vec2(bottom.y, 3.0))) / size.xyxy;
		vec4 bottom_left_line = (cell_id.xyxy + vec4(vec2(-2.0, 1.0 + bottom_left.x), vec2(1.0, 1.0 + bottom_left.y))) / size.xyxy;
		vec4 left_line = (cell_id.xyxy + vec4( vec2(-1.0 + left.x, -1.0), vec2(-1.0 + left.y, 2.0))) / size.xyxy;
		vec4 top_left_line = (cell_id.xyxy + vec4(vec2(-2.0, -1.0 + top_left.x), vec2(1.0, -1.0 + top_left.y))) / size.xyxy;

		// if above h cut

		if (!point_left_of_line(current_line, uv)) {
			// if left of v cut
			if (point_left_of_line(top_line, uv)) {
				a = get_line_intersection(top_left_line, left_line);
				b = get_line_intersection(top_line, top_left_line);
				c = get_line_intersection(current_line, top_line);
				d = get_line_intersection(current_line, left_line);
				color = vec3(1.0, 0.0, 0.0);
			} else {
				a = get_line_intersection(top_right_line, top_line);
				b = get_line_intersection(right_line, top_right_line);
				c = get_line_intersection(current_line, right_line);
				d = get_line_intersection(current_line, top_line);

				color = vec3(0.0, 1.0, 0.0);
			}
		} else {
			// if right of v cut
			if (!point_left_of_line(bottom_line, uv)) {
				a = get_line_intersection(current_line, bottom_line);
				b = get_line_intersection(current_line, right_line);
				c = get_line_intersection(bottom_right_line, right_line);
				d = get_line_intersection(bottom_right_line, bottom_line);

				color = vec3(0.0, 0.0, 1.0);
			} else {
				a = get_line_intersection(left_line, current_line);
				b = get_line_intersection(bottom_line, current_line);
				c = get_line_intersection(bottom_line, bottom_left_line);
				d = get_line_intersection(left_line, bottom_left_line);

				color = vec3(1.0, 1.0, 0.0);
			}
		}
		brick_uv.xy = (invBilinear(uv, a, b, c, d));
		rect = generate_rect(a, b, c, d);
	// Vertical
	} else { 
		// The nine lines for horizontal cuts
		vec4 current_line = (cell_id.xyxy + vec4(vec2(current.x, -1.0), vec2(current.y, 2.0))) / size.xyxy;
		vec4 top_line = (cell_id.xyxy + vec4(vec2(-1.0, -1.0 + top.x), vec2(2.0, -1.0 + top.y))) / size.xyxy;
		vec4 top_right_line = (cell_id.xyxy + vec4(vec2(1.0 + top_right.x, -2.0), vec2(1.0 + top_right.y, 1.0))) / size.xyxy;
		vec4 right_line = (cell_id.xyxy + vec4(vec2(0.0, right.x), vec2(3.0, right.y))) / size.xyxy;
		vec4 bottom_right_line = (cell_id.xyxy + vec4(vec2(1.0 + bottom_right.x, 0.0), vec2(1.0 + bottom_right.y, 3.0))) / size.xyxy;
		vec4 bottom_line = (cell_id.xyxy + vec4(vec2(-1.0, 1.0 + bottom.x), vec2(2.0, 1.0 + bottom.y))) / size.xyxy;
		vec4 bottom_left_line = (cell_id.xyxy + vec4(vec2(-1.0 + bottom_left.x, 0.0), vec2(-1.0 + bottom_left.y, 3.0))) / size.xyxy;
		vec4 left_line = (cell_id.xyxy + vec4( vec2(-2.0, left.x), vec2(1.0, left.y))) / size.xyxy;
		vec4 top_left_line = (cell_id.xyxy + vec4(vec2(-1.0 + top_left.x, -2.0), vec2(-1.0 + top_left.y, 1.0))) / size.xyxy;

		// if left of v cut
		if (point_left_of_line(current_line, uv)) {
			// if above h cut
			if (!point_left_of_line(left_line, uv)) {
				a = get_line_intersection(top_left_line, top_line);
				b = get_line_intersection(current_line, top_line);
				c = get_line_intersection(current_line, left_line);
				d = get_line_intersection(top_left_line, left_line);

				color = vec3(1.0, 0.0, 1.0);
			} else {
				a = get_line_intersection(bottom_left_line, left_line);
				b = get_line_intersection(current_line, left_line);
				c = get_line_intersection(current_line, bottom_line);
				d = get_line_intersection(bottom_left_line, bottom_line);

				color = vec3(1.0, 0.5, 0.0);
			}
		} else {
			// if above h cut
			if (!point_left_of_line(right_line, uv)) {
				a = get_line_intersection(current_line, top_line);
				b = get_line_intersection(top_right_line, top_line);
				c = get_line_intersection(top_right_line, right_line);
				d = get_line_intersection(current_line, right_line);

				color = vec3(0.0, 1.0, 1.0);
			} else {
				a = get_line_intersection(current_line, right_line);
				b = get_line_intersection(bottom_right_line, right_line);
				c = get_line_intersection(bottom_right_line, bottom_line);
				d = get_line_intersection(current_line, bottom_line);

				color = vec3(0.5, 1.0, 0.0);
			}
		}
		brick_uv.xy = (invBilinear(uv, a, b, c, d));
		rect = generate_rect(a, b, c, d);
	}

	brick_fill = vec4(fract(rect.xy), rect.zw - rect.xy);

	brick_fill *= 4096.0;
	brick_fill = round(brick_fill);
	brick_fill /= 4096.0;

	brick_uv.z = rand(brick_fill.xy);

	corner_uv.xy = brick_fill.zw * 2.0 / corner * (1.0 - (2.0 * abs(brick_uv.xy - 0.5)));
	corner_uv.x = brick_uv.x < 0.5 ? corner_uv.x : 1.0 - corner_uv.x;
	corner_uv.y = brick_uv.y < 0.5 ? corner_uv.y : 1.0 - corner_uv.y;
	corner_uv.z = rand( floor(brick_uv.xy * 2.0) + brick_fill.xy );
	// Calculate corner bb
	float half_corner_size = 1.0 / max(size.x, size.y) * corner * 0.5;
	vec2 top_centers = brick_uv.x < 0.5 ? a + (normalize(d - a) + normalize(b - a)) * half_corner_size : b + (normalize(c - b) + normalize(a - b)) * half_corner_size; 
	vec2 bottom_centers = brick_uv.x < 0.5 ? d + (normalize(a - d) + normalize(c - d)) * half_corner_size : c + (normalize(b - c) + normalize(d - c)) * half_corner_size; 
	corner_fill.xy = brick_uv.y < 0.5 ? top_centers : bottom_centers;
	corner_fill.xy -= half_corner_size;
	corner_fill.zw = vec2(half_corner_size * 2.0);
	corner_fill = fract(round(corner_fill*grid_size)/grid_size);

	// Render the bricks
	bevel /= max(size.x, size.y) / 2.0;
	mortar /= max(size.x, size.y) / 2.0;
	float brick;
	vec2 dist = (min(brick_uv.xy, 1.0 - brick_uv.xy) * -2.0);
	dist *=  brick_fill.zw;
	dist += vec2(round_radius+mortar);
	brick = length(max(dist, vec2(0))) + min(max(dist.x, dist.y), 0.0) - round_radius;
	brick = clamp(-brick/bevel, 0.0, 1.0);

	return brick;
}

