vec2 $(name)_distance_h(vec2 uv) {
	vec2 e = vec2(1.0/$s, 0.0);
	int steps = int($s*$d/max(1.0, $p));
	float rv = 0.0;
	vec2 source_uv;
	float source_h;
	float best_source_h = 0.0;
	float h;
	float best_h = 0.0;
	float best_x = 0.0;
	for (int i = -steps; i <= steps; ++i) {
		source_uv = uv+float(i)*e;
		source_h = $in(source_uv);
		h = source_h-abs(float(i))*e.x/$d;
		if (h > best_h) {
			best_h = h;
			best_source_h = source_h;
			best_x = source_uv.x;
		}
	}
	return vec2(best_source_h, best_x);
}

float $(name)_distance_v(vec2 uv) {
	int steps = int($s*$d/max(1.0, $p));
	float best_h = 0.0;
	float l;
	float h;
	vec2 in_uv = uv;
	for (int i = -steps; i <= steps; ++i) {
		in_uv.y = uv.y+float(i)/$s;
		vec2 h_x = pack_4x16_to_2x32($in(in_uv));
		l = length(vec2(h_x.y-uv.x, float(i)/$s));
		if (l < $d) {
			h = h_x.x-l*$p/$d;
			if (h > best_h) {
				best_h = h;
			}
		}
	}
	return best_h;
}

