float $(name)_curve( vec2 p, vec2 o ){
	float a = $in(p+o);
	float b = $in(p-o);
	float c = $in(p+o*vec2(1.0,-1.0));
	float d = $in(p-o*vec2(1.0,-1.0));
	return -a - b - c - d;
}

float $(name)_curvature_map(vec2 p, float r, float q){
	float s = r/q;
	float H = $in(p)*4.0;
	float v = 0.0;
	for(float ox = 0.0; ox < q; ox++ ){
		for(float oy = 0.0; oy < q; oy++ ){
			vec2 o = vec2(ox, oy);
			float c = $(name)_curve(p, o*s);
			v += (H + c) * ((r-length(o*s)) / r);
		}
	}
	return v/(q*q);
}

float $(name)_curvature(vec2 uv, float quality, float strength, float radius) {
	float c = $(name)_curvature_map(uv, 0.050 * radius, quality)*strength / radius;
	return 0.5 + c;
}

shader_model.global:
float smin(float d1, float d2, float k) {
	float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
	return mix( d2, d1, h ) - k*h*(1.0-h);
}

float smax(float d1, float d2, float k) {
	float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
	return mix( d2, d1, h ) + k*h*(1.0-h); 
}

float sphere(vec2 uv, vec2 c, float r) {
	uv -= c;
	uv /= r;
	return 2.0*r*sqrt(max(0.0, 1.0-dot(uv, uv)));
}

shader_model.code:
vec2 position_$(name_uv) = $uv - 0.5;
float length_$(name_uv) = length(position_$(name_uv));
float spiral_$(name_uv) = (1.0 + sin(($use_perspective ? (($perspective * 6.0) / length_$(name_uv)) : (length_$(name_uv) / ($perspective / 6.0))) + (circular_gradient(position_$(name_uv)) * 6.28318530718 * $amount))) / 2.0;

shader_model.global:
float circular_gradient(vec2 uv) {
  return fract(0.15915494309 * atan(uv.x, uv.y));
}

