vec3 $(name_uv)_center_uv = vec3(0.0);
vec4 $(name_uv)_rch = splatter_$(name)($uv, int($count), $(name_uv)_instance_uv, $(name_uv)_center_uv, vec2(float($seed)));

shader_model.instance:
vec4 splatter_$(name)(vec2 uv, int count, inout vec3 instance_uv, inout vec3 center_uv, vec2 seed) {
	float c = 0.0;
	vec3 rc = vec3(0.0);
	vec3 rc1;
	for (int i = 0; i < count; ++i) {
		seed = rand2(seed);
		rc1 = rand3(seed);
		vec2 pos = fract(seed+vec2(0.5));
		float mask = $mask(pos);
		if (mask > 0.01) {
			vec2 pv = fract(uv - seed)-vec2(0.5);
			seed = rand2(seed);
			float angle = (seed.x * 2.0 - 1.0) * $rotate * 0.01745329251;
			float ca = cos(angle);
			float sa = sin(angle);
			pv = vec2(ca*pv.x+sa*pv.y, -sa*pv.x+ca*pv.y);
			pv *= (seed.y-0.5)*2.0*$scale+1.0;
			pv /= vec2($scale_x, $scale_y);
			pv += vec2(0.5);
			seed = rand2(seed);
			vec2 clamped_pv = clamp(pv, vec2(0.0), vec2(1.0));
			if (pv.x != clamped_pv.x || pv.y != clamped_pv.y) {
				continue;
			}
			vec2 full_uv = pv;
			pv = get_from_tileset($inputs, seed.x, pv);
			float c1 = $in.variation(pv, $variations ? seed.x : 0.0)*mask*(1.0-$value*seed.x);
			c = max(c, c1);
			rc = mix(rc, rc1, step(c, c1));
			instance_uv = mix(instance_uv, vec3(full_uv, seed.x), step(c, c1));
			center_uv = mix(center_uv, vec3(pos, seed.x), step(c, c1));
		}
	}
	return vec4(rc, c);
}

vec4 splatter_$(name)(vec2 uv, int count, vec2 seed) {
	vec4 c = vec4(0.0);
	for (int i = 0; i < count; ++i) {
		seed = rand2(seed);
		float mask = $mask(fract(seed+vec2(0.5)));
		if (mask > 0.01) {
			vec2 pv = fract(uv - seed)-vec2(0.5);
			seed = rand2(seed);
			float angle = (seed.x * 2.0 - 1.0) * $rotate * 0.01745329251;
			float ca = cos(angle);
			float sa = sin(angle);
			pv = vec2(ca*pv.x+sa*pv.y, -sa*pv.x+ca*pv.y);
			pv *= (seed.y-0.5)*2.0*$scale+1.0;
			pv /= vec2($scale_x, $scale_y);
			pv += vec2(0.5);
			seed = rand2(seed);
			if (pv != clamp(pv, vec2(0.0), vec2(1.0))) {
				continue;
			}
			$select_inputs
			vec4 n = $in.variation(pv, $variations ? seed.x : 0.0);
			float na = n.a*mask*(1.0-$opacity*seed.x);
			float a = (1.0-c.a)*(1.0*na);
			c = mix(c, n, na);
		}
	}
	return c;
}

shader_model.global:
/* https://iquilezles.org/articles/distfunctions2d/, https://www.shadertoy.com/view/4lcBWn */
vec2 distance_to_segment(vec2 p, vec3 b, vec3 a) {
	p  -= a.xy;
	b.xy -= a.xy;
	float h = dot(b.xy, b.xy);
	vec2  q = vec2(dot(p,vec2(b.y,-b.x)), dot(p,b.xy))/h;

	q.x = abs(q.x);

	float cz = a.z-b.z;
	vec2  c = vec2(sqrt(h-cz*cz), cz);

	float k = c.x*q.y - c.y*q.x;
	float m = dot(c, q);
	float n = dot(q, q);

		 if( k < 0.0 ) return vec2(sqrt(h*(n)) - a.z, 0.0);
	else if( k > c.x ) return vec2(sqrt(h*(n+1.0-2.0*q.y)) - b.z, 1.0);
					   return vec2(m					   - a.z, k/c.x);
}

float distance_to_cubic_bezier_2(vec2 uv, vec4 a, vec4 b, vec4 c, vec4 d, float t0, float t1, float s) {
	float rv = 100000000000.0;
	t0 = clamp(t0, 0.0, 1.0);
	t1 = clamp(t1, 0.0, 1.0);
	float bt = t0;

	vec4 lp = d+t0*(c+t0*(b+t0*a));
	for (float t = t0+s; t < t1+0.5*s; t += s) {
		vec4 p = d+t*(c+t*(b+t*a));
		vec2 dts = distance_to_segment(uv, lp.xyz, p.xyz);
		if (rv > dts.x) {
			rv = dts.x;
			bt = t-s*p.y;
		}
		lp = p;
	}
	return clamp(bt, 0.0, 1.0);
}

vec4 distance_to_cubic_bezier(vec2 uv, vec4 p0, vec4 p1, vec4 p2, vec4 p3) {
	float rv = 1000.0;
	vec4 a = p3-p0+3.0*(p1-p2);
	vec4 b = 3.0*(p0+p2-2.0*p1);
	vec4 c = 3.0*(p1-p0);
	vec4 d = p0;
	float t = distance_to_cubic_bezier_2(uv, a, b, c, d, 0.0, 1.0, 0.1);
	t = distance_to_cubic_bezier_2(uv, a, b, c, d, t-0.1, t+0.1, 0.01);
	t = distance_to_cubic_bezier_2(uv, a, b, c, d, t-0.01, t+0.01, 0.001);
	t = distance_to_cubic_bezier_2(uv, a, b, c, d, t-0.001, t+0.001, 0.0001);
	vec4 p = d+t*(c+t*(b+t*a));
	vec2 tangent = (3.0*a.xy*t+2.0*b.xy)*t+c.xy;
	tangent = vec2(tangent.y, -tangent.x);
	return vec4(p.w, sign(dot(uv-p.xy, tangent))*length(p.xy-uv)/p.z, sign(dot(uv-p.xy, tangent))*length(p.xy-uv), 1.0);
}

