vec4 $(name)_splines(vec2 uv) {
	vec2 edge_uv = vec2(0.0, 10000000.0);
	float closest = 1000.0;
	float signed_distance = 10000000.0;
	for (int i = 0; i < $splines.length(); i += 4) {
		vec4 d = distance_to_cubic_bezier(uv, $splines[i], $splines[i+1], $splines[i+2], $splines[i+3]);
		if (abs(edge_uv.y) > abs(d.y)) {
			edge_uv = d.xy;
		}
		if (abs(closest) > abs(d.z)) {
			closest = d.z;
		}
	}
	if (abs(edge_uv.y) < 1.0) {
		return $in_edge(vec2(edge_uv.x, 0.5+0.5*edge_uv.y));
	} else if (closest > 0.0) {
		return $in_fill(uv);
	}
	return vec4(0.0);
}

vec4 supersample_$(name)(vec2 uv, float size, int count, float width) {
	vec4 rv = vec4(0.0);
	vec2 step_size = vec2(width)/size/float(count);
	uv -= vec2(0.5)/size;
	for (int x = 0; x < count; ++x) {
		for (int y = 0; y < count; ++y) {
			rv += $in(uv+(vec2(float(x), float(y))+vec2(0.5))*step_size);
		}
	}
	return rv/float(count*count);
}

