vec3 $(name)_symmetric_nearest_neighbor(vec2 uv, int kernel_size) {
	kernel_size += ~(kernel_size & 1);
	vec2 one_pixel = vec2(1.0 / $size);
	int half_size = kernel_size / 2;
	vec3 v = $in(uv).rgb;
	vec4 mean_color = vec4(0.0);
	for (int y = 0; y <= half_size; y++){
		for (int x = -half_size; x <= half_size; x++){
			vec3 v1 = $in(uv + vec2(float(x), float(y)) * one_pixel);  
			vec3 v2 = $in(uv + vec2(float(-x), float(-y)) * one_pixel);
			vec3 d1 = abs(v - v1);
			vec3 d2 = abs(v - v2);
			vec4 rv = vec4(((d1[0] < d2[0]) ? v1[0] : v2[0]),
				((d1[1] < d2[1]) ? v1[1] : v2[1]),
				((d1[2] < d2[2]) ? v1[2] : v2[2]),1);
			mean_color += rv;
		}
	}
	return mean_color.rgb / float(kernel_size*(half_size + 1));
}

