vec3 tex3d_rotate(vec3 p, vec3 a) {
	vec3 rv;
	float c;
	float s;
	c = cos(a.x);
	s = sin(a.x);
	rv.x = p.x;
	rv.y = p.y*c+p.z*s;
	rv.z = -p.y*s+p.z*c;
	c = cos(a.y);
	s = sin(a.y);
	p.x = rv.x*c+rv.z*s;
	p.y = rv.y;
	p.z = -rv.x*s+rv.z*c;
	c = cos(a.z);
	s = sin(a.z);
	rv.x = p.x*c+p.y*s;
	rv.y = -p.x*s+p.y*c;
	rv.z = p.z;
	return rv;
}

// Based on https://www.shadertoy.com/view/ldl3W8
// The MIT License
// Copyright © 2013 Inigo Quilez
vec4 iq_voronoi_3d(vec3 x, vec3 size, float randomness, vec2 seed) {
	vec3 n = floor(x);
	vec3 f = fract(x);

	vec3 mg, mr, mc;
	float md = 8.0;
	for (int k=-1; k<=1; k++)
	for (int j=-1; j<=1; j++)
	for (int i=-1; i<=1; i++) {
		vec3 g = vec3(float(i),float(j),float(k));
		vec3 ngs = mod(n + g + size, size);
		vec3 o = randomness*rand3(seed + ngs.xy + ngs.yz);
		vec3 c = g + o;
		vec3 r = c - f;
		float d = dot(r,r);

		if (d<md) {
			mc = c;
			md = d;
			mr = r;
			mg = g;
		}
	}

	md = 8.0;
	for (int k=-2; k<=2; k++)
	for (int j=-2; j<=2; j++)
	for (int i=-2; i<=2; i++) {
		vec3 g = mg + vec3(float(i),float(j),float(k));
		vec3 ngs = mod(n + g + size, size);
		vec3 o = randomness*rand3(seed +  + ngs.xy + ngs.yz);
		vec3 r = g + o - f;
		if (dot(r,r)>0.00001)
	   		md = min(md, dot(0.5*(mr+r), normalize((r-mr))));
	}

	return vec4(md, mc+n);
}

vec4 voronoi_3d(vec3 uv, vec3 size, float intensity, float randomness, float seed) {
	uv *= size;
	vec4 v = iq_voronoi_3d(uv, size, randomness, rand2(vec2(seed, 1.0-seed)));
	return vec4(v.yzw, v.x);
}

