vec4 tiler_$(name)(vec2 uv, vec2 tile, int overlap, inout vec3 instance_uv, inout vec2 center_uv, vec2 _seed) {
	float c = 0.0;
	vec3 rc = vec3(0.0);
	vec3 rc1;
	for (int dx = -overlap; dx <= overlap; ++dx) {
		for (int dy = -overlap; dy <= overlap; ++dy) {
			vec2 pos = uv*tile+vec2(float(dx), float(dy)); pos = fract((floor(mod(pos, tile))+vec2(0.5))/tile)-vec2(0.5);
			vec2 seed = rand2(pos+_seed);
			rc1 = rand3(seed);
			vec2 tile_index = floor(uv * tile) + vec2(float(dx), float(dy));
			pos += vec2(($fixed_offset/tile.x)*mod(floor(mod(tile_index.y+0.5, tile.y)), 2.0), 0.0)+$offset*seed/tile;
			float mask = $mask(fract(pos+vec2(0.5)));
			if (mask > 0.01) {
				vec2 pv = fract(uv - pos)-vec2(0.5);
				seed = rand2(seed);
				float angle = (seed.x * 2.0 - 1.0) * $rotate * 0.01745329251;
				float ca = cos(angle);
				float sa = sin(angle);
				pv = vec2(ca*pv.x+sa*pv.y, -sa*pv.x+ca*pv.y);
				pv *= (seed.y-0.5)*2.0*$scale+1.0;
				pv /= vec2($scale_x, $scale_y);
				pv += vec2(0.5);
				seed = rand2(seed);
				vec2 clamped_pv = clamp(pv, vec2(0.0), vec2(1.0));
				if (pv.x != clamped_pv.x || pv.y != clamped_pv.y) {
					continue;
				}
				vec2 full_uv = pv;
				pv = get_from_tileset($inputs, seed.x, pv);
				float c1 = $in.variation(pv, $variations ? seed.x : 0.0)*mask*(1.0-$value*seed.x);
				rc = mix(rc, rc1, step(c, c1));
				instance_uv = mix(instance_uv, vec3(full_uv, seed.x), step(c, c1));
				center_uv = mix(center_uv, pos+vec2(0.5), step(c, c1));
				c = max(c, c1);
			}
		}
	}
	return vec4(rc, c);
}

vec4 tiler_$(name)(vec2 uv, vec2 tile, int overlap, inout vec3 instance_uv, float _seed) {
	float c = 0.0;
	vec2 map_uv = vec2(0.0);
	for (int dx = -overlap; dx <= overlap; ++dx) {
		for (int dy = -overlap; dy <= overlap; ++dy) {
			vec2 pos = uv*tile+vec2(float(dx), float(dy)); pos = fract((floor(mod(pos, tile))+vec2(0.5))/tile)-vec2(0.5);
			float mask = $mask(fract(pos+vec2(0.5)));
			if (mask > 0.01) {
				vec2 pv = fract(uv - pos)-vec2(0.5);
				pos = fract(pos+vec2(0.5));
				pv -= vec2($translate_x*$tr_x(pos), $translate_y*$tr_y(pos))/tile;
				float angle = $r(pos) * $rotate * 0.01745329251;
				float ca = cos(angle);
				float sa = sin(angle);
				pv = vec2(ca*pv.x+sa*pv.y, -sa*pv.x+ca*pv.y);
				pv /= vec2($scale_x*$sc_x(pos), $scale_y*$sc_y(pos));
				pv += vec2(0.5);
				vec2 clamped_pv = clamp(pv, vec2(0.0), vec2(1.0));
				if (pv.x != clamped_pv.x || pv.y != clamped_pv.y) {
					continue;
				}
				vec2 seed = rand2(vec2(_seed)+pos);
				vec2 full_uv = pv;
				pv = get_from_tileset($inputs, seed.x, pv);
				float c1 = $in.variation(pv, $variations ? seed.x : 0.0)*mask;
				c = max(c, c1);
				map_uv = mix(map_uv, pos, step(c, c1));
				instance_uv = mix(instance_uv, vec3(full_uv, seed.x), step(c, c1));
			}
		}
	}
	return vec4(map_uv, 0.0, c);
}

vec4 tiler_$(name)(vec2 uv, vec2 tile, int overlap, float _seed, out vec2 outmapuv) {
	// $seed
	vec4 c = vec4(0.0);
	outmapuv = vec2(0.0);
	for (int dx = -overlap; dx <= overlap; ++dx) {
		for (int dy = -overlap; dy <= overlap; ++dy) {
			vec2 pos = uv*tile+vec2(float(dx), float(dy)); pos = fract((floor(mod(pos, tile))+vec2(0.5))/tile)-vec2(0.5);
			float mask = $mask(fract(pos+vec2(0.5)));
			if (mask > 0.01) {
				vec2 pv = fract(uv - pos)-vec2(0.5);
				pos = fract(pos+vec2(0.5));
				pv -= vec2($translate_x*$tr_x(pos), $translate_y*$tr_y(pos))/tile;
				float angle = $r(pos) * $rotate * 0.01745329251;
				float ca = cos(angle);
				float sa = sin(angle);
				pv = vec2(ca*pv.x+sa*pv.y, -sa*pv.x+ca*pv.y);
				pv /= vec2($scale_x*$sc_x(pos), $scale_y*$sc_y(pos));
				pv += vec2(0.5);
				vec2 clamped_pv = clamp(pv, vec2(0.0), vec2(1.0));
				if (pv.x != clamped_pv.x || pv.y != clamped_pv.y) {
					continue;
				}
				vec2 seed = rand2(vec2(_seed)+pos);
				$select_inputs
				vec4 n = $in.variation(pv, $variations ? seed.x : 0.0);
				float na = n.a*mask;
				outmapuv = mix(outmapuv, pos, step(c.a, na));
				c = mix(c, n, na);
			}
		}
	}
	return c;
