// Based on https://www.shadertoy.com/view/ss3fW4
const float s3 = 0.866025;

vec3 sdTriEdges(vec2 p) {
	return vec3(
		dot(p, vec2(0,-1)),
		dot(p, vec2(s3, 0.5)),
		dot(p, vec2(-s3, 0.5))
	);
}

float sdTri(vec2 p) {
	vec3 t = sdTriEdges(p);
	return max(t.x, max(t.y, t.z));
}

vec3 primaryAxis(vec3 p) {
	vec3 a = abs(p);
	return (1.0-step(a.xyz, a.yzx))*step(a.zxy, a.xyz)*sign(p);
}

vec3 sdgBorder(vec2 pt1, vec2 pt2) {	
	vec3 tbRel = sdTriEdges(pt2 - pt1);	
	vec3 axis = primaryAxis(tbRel);

	vec2 gA = vec2(0,-1);
	vec2 gB = vec2(s3, 0.5);
	vec2 gC = vec2(-s3, 0.5);

	vec2 norA = gC * axis.x + gA * axis.y + gB * axis.z;
	vec2 norB = gB * -axis.x + gC * -axis.y + gA * -axis.z;

	vec2 dir = gA * axis.x + gB * axis.y + gC * axis.z;
	vec2 corner = dir * dot(dir, pt1 - pt2) * 2.0/3.0;

	mat2 r90 = mat2(vec2(0.0,-1.0),vec2(1.0,0.0));

	bool isEdge = axis.x + axis.y + axis.z < 0.0;

	if (isEdge) {
		corner = pt2 + corner;
		vec2 ca = corner + min(0.0, dot(corner, -norA)) * norA;
		vec2 cb = corner + max(0.0, dot(corner, -norB)) * norB;
		float side = step(dot(corner, dir * r90), 0.0);
		corner = mix(cb, ca, side);
	} else {
		corner = pt1 - corner;
		vec2 ca = corner + max(0.0, dot(corner, -norA)) * norA;
		vec2 cb = corner + min(0.0, dot(corner, -norB)) * norB;
		float side = step(dot(corner, dir * r90), 0.0);
		corner = mix(ca, cb, side);
	}

	vec2 nor = normalize(corner);
	float d = length(corner);
	return vec3(abs(d), nor);
}

float vmax(vec3 v) { return max(v.x, max(v.y, v.z)); }

vec4 cellPoint(vec2 n, vec2 f, vec2 cell, float r, float seed, vec2 s, vec2 st) {
	vec2 coord = n + cell;
	vec2 o = r*rand2(seed + mod(n + cell + s, s));
	vec2 point = cell + o - f;
	point *= st;
	return vec4(point, coord);
}

vec2 tri_coord(vec2 x, vec2 s, vec2 st, float r, float seed) {
	vec2 n = floor(x);
	vec2 f = fract(x);

	vec2 closestCoord;

	const int reach = 2;
	float closestDist = 8.0;
	for( int j = -reach; j <= reach; j++ )
	for( int i = -reach; i <= reach; i++ )
	{
		vec2 cell = vec2(float(i), float(j));
		vec4 point = cellPoint(n,f,cell,r,seed,s,st);

		float dist = vmax(sdTriEdges(point.xy));

		if( vmax(sdTriEdges(point.xy)) < closestDist )
		{
			closestDist = dist;
			closestCoord = point.zw;
		}
	}
	return closestCoord;
}

mat3 tri_voronoi( vec2 x, vec2 s, vec2 st, float r, float seed) {	
	x *= s;
	vec2 n = floor(x);
	vec2 f = fract(x);

	vec2 closestCell, closestPoint, nor;

	const int reach = 3;
	float closestDist = 8.0;

	for( int j = -reach; j <= reach; j++ )
	for( int i = -reach; i <= reach; i++ )
	{
		vec2 cell = vec2(float(i), float(j));
		vec2 point = cellPoint(n,f,cell,r,seed,s,st).xy;

		float dist = sdTri(point);

		if( dist < closestDist )
		{
			closestDist = dist;
			closestPoint = point;
			closestCell = cell;
		}
	}

	closestDist = 8.0;
	for( int j = -reach-1; j <= reach+1; j++ )
	for( int i = -reach-1; i <= reach+1; i++ )
	{
		vec2 cell = closestCell + vec2(float(i), float(j));
		vec2 coord = n + cell;
			vec2 o = r*rand2(seed + mod(n + cell + s, s));
			vec2 point = cell + o - f;
		point *= st;

		float dist = sdTri(closestPoint - point);

		if( dist > 0.00001 ) {
			vec3 sdg = sdgBorder(closestPoint, point);
			if (sdg.x < closestDist) {
				closestDist = sdg.x;
				nor = sdg.zy;
			}
		}
	}

	return mat3(
		vec3(closestDist,closestPoint),
		vec3(nor,0),
		vec3(tri_coord(x,s,st,r,seed),0));
}

