vec2 $(name)_slope(vec2 uv, float epsilon) {
	float dx = $hm(fract(uv+vec2(epsilon, 0.0)))-$hm(fract(uv-vec2(epsilon, 0.0)));
	float dy = $hm(fract(uv+vec2(0.0, epsilon)))-$hm(fract(uv-vec2(0.0, epsilon)));
	return cos($angle*0.01745329251)*vec2(dx, dy)+sin($angle*0.01745329251)*vec2(-dy, dx);
}

float $(name)_dilate(vec2 uv) {
	float e = 1.0/$s;
	float v = 0.0;
	for (float x = 0.0; x <= $d; x += e) {
		v = max(v, $in(fract(uv))*(1.0-x/$d*$a));
		vec2 delta = $(name)_slope(uv, e);
		if (delta.x == 0.0 && delta.y == 0.0) {
			break;
		}
		uv += e*normalize(delta);
	}
	return v;
}

vec2 $(name)_slope(vec2 uv, float epsilon) {
	float dx = $hm(fract(uv+vec2(epsilon, 0.0)))-$hm(fract(uv-vec2(epsilon, 0.0)));
	float dy = $hm(fract(uv+vec2(0.0, epsilon)))-$hm(fract(uv-vec2(0.0, epsilon)));
	return vec2($mode);
}

float $(name)_dilate(vec2 uv, vec2 slope) {
	float e = 1.0/$s;
	float v = 0.0;
	for (float x = 0.0; x <= $d; x += e) {
		v = max(v, $in(fract(uv))*(1.0-x/$d*$a));
		uv += e*normalize($(name)_slope(uv, 0.0001));
	}
	return v;
}

shader_model.global:
float wavelet(vec2 uv, vec2 size, float s, float frequency, float offset) {
	uv = mod(uv, size);
	vec2 seed = fract(floor(uv)*0.1236754+vec2(s));
	uv = fract(uv);
	vec2 ruv = uv-0.5;
	float a = rand(seed)*6.28;
	float ca = cos(a);
	float sa = sin(a);
	ruv = vec2(ca*ruv.x + sa*ruv.y, -sa*ruv.x + ca*ruv.y);
	return (0.5*sin(ruv.x*6.28*frequency+offset)+0.5)*max(0.0, 1.0-2.0*length(uv-vec2(0.5)));
}

float wavelet_noise(vec2 uv, vec2 size, int iterations, float persistence, float seed, float frequency, float offset, float type) {
	float rv = 0.0;
	float acc = 0.0;
	vec2 seed2 = rand2(vec2(seed));
	vec2 local_uv = uv * size;
	float q = 1.0;
	for (int i = 0; i < iterations; ++i) {
		rv += q*wavelet(local_uv, size, seed, frequency, offset);
		rv += q*wavelet(local_uv+vec2(0.5), size, seed+0.1, frequency, offset);
		acc += q;
		if (type > 0.0) {
			local_uv += type*uv;
			size += vec2(type);
		} else {
			local_uv *= -type;
			size *= -type;
		}
		local_uv += seed2; 
		seed2 = rand2(seed2);
		q *= persistence;
		seed += 0.1;
	}
	return rv / acc;
}

