float oldweave(vec2 uv, vec2 count, float width) {
	uv *= count;
	float c = (sin(3.1415926*(uv.x+floor(uv.y)))*0.5+0.5)*step(abs(fract(uv.y)-0.5), width*0.5);
	c = max(c, (sin(3.1415926*(1.0+uv.y+floor(uv.x)))*0.5+0.5)*step(abs(fract(uv.x)-0.5), width*0.5));
	return c;
}

vec3 weave(vec2 uv, vec2 count, float stitch, float width_x, float width_y) {
	uv *= stitch;
	uv *= count;
	float c1 = (sin( 3.1415926 / stitch * (uv.x + floor(uv.y) - (stitch - 1.0))) * 0.25 + 0.75 ) *step(abs(fract(uv.y)-0.5), width_x*0.5);
	float c2 = (sin(3.1415926 / stitch * (1.0+uv.y+floor(uv.x) ))* 0.25 + 0.75 )*step(abs(fract(uv.x)-0.5), width_y*0.5);
	return vec3(max(c1, c2), 1.0-step(c1, c2), 1.0-step(c2, c1));
}

vec3 random_weave(vec2 uv, vec2 size, vec2 width, float stitch, float random, float seed) {
	vec2 seed2 = rand2(vec2(seed, 1.0-seed));

	vec2 offset = vec2(0.5, 0.0);
	vec2 xy_offset = floor(uv * size * stitch + offset );

	vec2 offset2 = vec2(1.0, -0.5);
	vec2 xy_offset2 = floor(uv * size * stitch + offset2 );

	float f0 = rand(seed2+mod(xy_offset, size * stitch));
	float checker0 = mod(mod(xy_offset.x + xy_offset.y, size.x * stitch), stitch * 2.0) < stitch ? 0.0 : 1.0;
	checker0 = f0 > random ? checker0 : floor(f0 * 2.0);

	float f1 = rand(seed2+mod(xy_offset+vec2(1.0, 0.0), size * stitch));
	float checker1 = mod(mod(xy_offset.x + 1.0 + xy_offset.y, size.x * stitch), stitch * 2.0) < stitch ? 0.0 : 1.0;
	checker1 = f1 > random ? checker1 : floor(f1 * 2.0);

	float f2 = rand(seed2+mod(xy_offset2, size * stitch));
	float checker2 = mod(mod(xy_offset2.x + xy_offset2.y, size.x * stitch), stitch * 2.0) < stitch ? 1.0 : 0.0;
	checker2 = f2 > random ? checker2 : 1.0 - floor(f2 * 2.0);

	float f3 = rand(seed2+mod(xy_offset2+vec2(0.0, 1.0), size * stitch));
	float checker3 = mod(mod(xy_offset2.x + 1.0 + xy_offset2.y, size.x * stitch), stitch * 2.0) < stitch ? 1.0 : 0.0;
	checker3 = f3 > random ? checker3 : 1.0 - floor(f3 * 2.0);

	float mixer = clamp( (fract(uv.x*size.x*stitch+offset.x) -.5) + .5, 0.0, 1.0 );
	float mixer2 = clamp( (fract(uv.y*size.y*stitch+offset2.y) -.5) + .5, 0.0, 1.0 );

	vec2 bands = fract(uv * size * stitch);
	bands = min(bands, 1.0 - bands) * 2.0;
	bands = step(1.0 - width, bands);

	float h_bands = mix(checker0, checker1, smoothstep(0.0, 1.0, mixer)) * 0.5 + 0.5;
	h_bands = min(h_bands, bands.y);
	float v_bands = mix(checker2, checker3, smoothstep(0.0, 1.0, mixer2)) * 0.5 + 0.5;
	v_bands = min(v_bands, bands.x);

	return vec3(max(h_bands, v_bands), 1.0-step(h_bands, v_bands), 1.0-step(v_bands, h_bands));
}
